export const CATALOG = {
  "aaltoilu": { t: "sinusoidal displacement along/across paths.", tags: ["deform","warp","wave"] },
  "adsr": { t: "a multi-segment envelope for t: attack, decay, sustain level and release as fractions of the loop. Starts and ends at zero, ideal for animations that appear, hold, and fade.", tags: ["animation","audio","math"] },
  "aggregate": { t: "WASP-style discrete aggregation: copies of a module (wired in, or built-in) snap together at bounding-box connectors with collision checks, growing a crystal-like assembly part by part. Wire Iterations to animate growth.", tags: ["animation","connect","physics","repeat","structural"] },
  "align": { t: "snaps the content bounding box left/centre/right and top/middle/bottom within margins.", tags: ["transform"] },
  "antenna": { t: "the analog-era rooftop antenna forest planted along a wired Roofline path (a Base Y baseline when unwired; the node only ADDS ink, so Merge the roofline alongside). The mast is the unit: each carries 1..Heads stacked heads and every head rolls its own type, size, boom tilt and element foreshortening — no two antennas are copies; Vary spreads mast heights 0.5–2.2×. Types: Yagi (folded dipole, shrinking directors), forward-swept Log-periodic, VHF/UHF combo fishbone, mesh Panel with X-brace, radial FM star, offset satellite Dish with LNB arm — and Mixed turns a share of sites into parapet-level dish clusters under the masts. Braces lean diagonal struts (or guy wires), Cables hangs catenaries between level mast tops and drops feedlines to the roof; Cartoon's Wonk bows booms, jitters elements, caps tips with dots and doubles the masts. Orientation Up keeps masts vertical on sloped roofs, Aim Same way points the whole neighbourhood at one transmitter. Oversized masts retry at 0.72× / 0.5× before skipping, keeping edges clean.", tags: ["structural","retro","repeat"] },
  "array": { t: "grid/linear repetition of the input with per-copy deltas.", tags: ["combine","grid"] },
  "arvo": { t: "a constant number.", tags: ["math"] },
  "asciiart": { t: "renders line work or an image as plottable ASCII characters in the single-stroke font. Source Lines rasterizes the wired paths into a density grid — the more line length in a cell, the darker its character; Source Image samples a loaded picture's darkness. Ramp orders characters light-to-dark (Custom takes your own string); characters missing from the stroke font fall back to uppercase or are skipped. Gamma bends the mapping, Invert flips it, Threshold leaves the lightest cells empty. Columns sets resolution; characters are real pen strokes, so the result plots like any other geometry — and loop letters (O 0 D Q 8 Ö, dots) come out as real closed shapes, so Pattern Fill, Container and the other region nodes see them.", tags: ["dots","grid","image","plants","region","text"] },
  "asteroids": { t: "vector-game asteroids: irregular polygons with in/out spikes (the classic silhouette), plus an optional player ship (triangle) and stray bullets. Jaggedness and vertex count shape the rocks.", tags: ["retro","space"] },
  "attractor": { t: "Clifford / De Jong maps or the Lorenz system iterated thousands of times, fitted to the sheet. In Lorenz mode the four sliders map to the system (a→rho, b→sigma, c→beta, d→speed) and Plane picks the projection (x-z / x-y / y-z). Polyline is one chaotic thread, Dashes the classic attractor dust.", tags: ["chaos","scientific"] },
  "barcode": { t: "vertical bars of varying width filled with boustrophedon strokes; a stark rhythm generator (feed it to Stretch).", tags: ["scientific"] },
  "belt": { t: "a tape threading between pulley circles like film through rollers, built from exact directed-circle tangents: Weave Alternate crosses the belt between pulleys (the serpentine look), Same side hugs them all one way, Random mixes per pulley. Pulleys are generated inside the Margin or wired in — every closed path becomes a pulley (centroid + mean radius; Polka Dots and Circle Pack work directly) — and Loose pulleys scatters extras the belt ignores. Order picks the visiting sequence, Loop closes the circuit, an open belt curls End wrap degrees around its end pulleys. The tape never cuts through a pulley: a straight run that would hit one deflects around it like tape pressing on a roller, and where a wide belt would pinch through itself at a tight wrap, Auto idlers inserts a small guide roller — every candidate fix is measured and reverted unless it genuinely helps. Belt width 0 is a single line; wider belts render as Edges or Ribbon (outline plus rail lines at Fill pitch, a closed capsule on an open belt). Gap lifts the belt off the pulley edge and a wide belt rides half its width further out so the inner edge clears by exactly Gap. Pulley draw adds outlines plus Rings or Spiral fills on a seeded Filled %. The Empty output carries every unfilled pulley circle as clean closed regions for a fill node, untouched by Style; Show tape / Show pulleys plot each part alone.", tags: ["connect","geometric","machine","scatter"] },
  "bg_fill": { t: "seven full-sheet background fills in one node, picked with Mode. Drape: concentric fur-stroke arc bands folded by sharp creases like hanging fabric. Magnet: iron-filing dashes tracing a two-pole field, Attract or Repel. Grain: dense woodgrain lines that part around voids — seeded blobs, an optional Crack, or whatever is wired. Scales: staggered fish-scale rows as a rain of vertical dashes (lovely with a light pen on dark paper). Torn: fine strokes fanning off a diagonal spine into a wobbly rip lens — wire a path into Void and IT becomes the rip, rays leaving it From center or Perpendicular (open lines ray both sides). Pleat: vertical lines pinched into a diamond pleat grid like folded wallpaper. Circles: greedy largest-first circle packing, tangent at Gap 0 for the Apollonian look; Rings fills every circle with concentric rings at Line pitch. The Void input works in every mode with Negative Space semantics: closed interiors cut out, and every wired line — open or closed — carves a Void clearance band, so a Ribbon clears its own channel; in Grain the flow also bends around wired shapes like riverbanks. Line pitch is the master density. Tip: two BG Fills on different pens with different modes make an instant layered backdrop.", tags: ["fill","flow","geometric","hatch","region","texture"] },
  "bitcrush": { t: "(deform) — sample-rate and bit-depth reduction: coarse resampling makes paths angular, grid quantization snaps coordinates. Consecutive duplicate points are removed.", tags: ["deform","grid","repeat"] },
  "blobmesh": { t: "a procedural 3D blob built to be sliced, wired straight into Mesh Slice with no STL round-trip. The body is 1-5 metaballs fused by a smooth-min union and solved as a star-shaped radius per direction, so overlapping balls melt into one swollen mass instead of reading as separate spheres; Blend sets how far they melt (0 leaves a hard crease). Placement is Seeded (Spread, Size variation, shuffled by the seed) or Manual, which exposes X/Y/Z and size per ball — drag a ball outwards and the surface stretches into a lobe behind it, the direct way to sculpt something asymmetric. Radius X/Y/Z squashes round to oval. Profile reshapes further: presets (Egg, Pear, Hourglass, Barrel, Teardrop) or any paths wired into the Profile input, read either as a Cross-section (the outline becomes the horizontal shape — wire a Superformula star and the blob goes star-shaped in plan) or as a Vertical profile (half-width as radius per height, the Sweep 3D convention); Profile amount blends it in, and at 0 the profile does nothing at all. Surface distortion is three seeded layers: fBm noise along the normal, angular Lobes and Vertical waves, finished with Twist and Taper. Outputs Wireframe (ring/meridian cage at View angle/elevation, no hidden-line removal, every Nth line), Silhouette (the true outline — edges where a front face meets a back face, chained, so interior folds appear too) and Mesh for Mesh Slice. The mesh is centred and normalised exactly like an imported STL, so both sources slice identically. Keep Rings x Segments low while sculpting and raise it before slicing.", tags: ["3d","mesh","noise","organic","structural"] },
  "blobrings": { t: "bold ink blobs with nested rings: each blob is a stadium (spine segment swept by a radius) so nesting is a true EROSION — rings keep the spine and shrink the radius, leaving slot-like centers in elongated blobs. All rings of a blob sample one coherent wobble field (quasi-parallel, hand-sloppy from per-ring center jitter); Weight vary doubles rings into thick strokes, Solid cores fill blobs black from halfway in, thin curved Connectors string nearest neighbours, Satellites scatter small ringed dots in the gaps, Cluster pulls placement toward the canvas center.", tags: ["connect","dots","organic","plants","round","scatter"] },
  "bluesprig": { t: "hand-drawn blueberry sprigs after an embroidered original: a wandering main stem with sharp little kinks, sparse side branches, berries as small circles on stalk tips (sometimes clustered), and loose open cup flowers. Tip mix balances berries against cups; Leaves adds pointed ovals; a light ink wobble is baked in — chain into Hand Drawn for more.", tags: ["nature","plants","round"] },
  "braille": { t: "Grade 1 braille as a grid of dot circles at standard geometry (2.5 mm dot pitch, 6 mm cell, 10 mm line at Scale 1). Letters a–z plus Nordic å/ä/ö; digits get the number sign, capitals the capital sign, punctuation follows the Finnish table; | starts a new line. Mirror flips the whole block like a stamp (cells reverse AND dot columns swap) for punching from the front and reading the embossed bumps from the back — chain into Needle Punch with Punch at: Centers to pierce every dot, or plot the circles directly with a pen. When the node is selected, an overlay shows each cell's letter above it, unmirrored and readable; unknown characters are skipped.", tags: ["grid","round","symmetry","text"] },
  "bridges": { t: "connects points of the input with bridge lines. Points from Path centers (Polka Dots / Phyllotaxis circles become nodes), Vertices (resampled at a spacing) or Endpoints; rules k-nearest, Within distance, Chain (one continuous nearest-neighbour stroke, split at long jumps), Source order (connects points in the order their paths arrive — Merge input order, so Single Markers join exactly as wired; Trim ends gives separated segments and Close loop returns to the first point, unless Max bridge has split the run), Hull (outline) (a closed convex outline around all the points — no interior lines, interior points excluded) or Delaunay edges. Trim ends stops each bridge short of its points so lines never pierce the dots.", tags: ["connect","dots","mesh","pathops","round"] },
  "broken_grid": { t: "a grid falling apart by regions, in the early-computer-art tradition. Every cell edge is its own seeded decision driven by two noise fields: Zones sets the size of the territories, Contrast sharpens them into hard either-or regions, Density scales everything and Mix couples the fields — at 0 vertical and horizontal zones live separate lives (columns of dashes here, rows there), at 1 they agree and the drawing becomes solid boxes against empty voids. Every drawn edge is a dash: Gap shortens it with per-edge jitter, Shift knocks it off the lattice, Doubles gives a share a second parallel stroke and Wobble bends them. A built-in guard scans the lattice for isolated swastika-reading motifs (both chiralities, arm lengths 1–2) and deterministically removes one bend edge from any it finds — motifs buried inside dense regions do not read and are left alone; the guard is always on by design.", tags: ["geometric","grid","retro"] },
  "brush_z": { t: "brush pressure for a real Z axis: encodes millimetres of plunge below pen-down contact into every point (third component) that the G-code export turns into simultaneous Z moves — the brush breathes while it draws. Eight waves oscillate along arc length (Sine / Triangle / Square / Pulse+Duty / Noise / Ramps / Constant) with Wavelength, Phase and per-stroke jitters; End taper eases pressure to zero at stroke ends; Ghost width previews the stroke envelope on its own pen. MUST be last in the chain — downstream modifiers strip the Z data. Bed-Z profiles only; servo mode ignores pressure.", tags: ["audio","noise","penout","wave"] },
  "burr_cluster": { t: "a clustered mass of overlapping seed pods grown by chaining noise-edged lobes. Each lobe fills with near-horizontal hatch (Angle jitter per pod, Speckle gaps, Wobble), lobes layer so internal seams read like pressed pods, and short bristle spikes radiate from every visible edge — silhouette and seams — with jittered angles and crossing X pairs. Blots splatters small filled ink dots.", tags: ["dots","hatch","nature","noise","pens","texture"] },
  "cables": { t: "tangled wires: inertia-driven noise walks with soft edge steering. Edges layout (cables enter and leave) or Pile; optional pen per cable.", tags: ["noise","organic"] },
  "cagewarp": { t: "(deform) — a seeded 2-6-cell FFD lattice bends everything smoothly; Pin edges keeps the canvas border still. Output clamped to the sheet.", tags: ["deform","grid","warp"] },
  "calib_sheet": { t: "a test sheet for measuring the machine rather than the pen: a square of exactly Size mm with both diagonals, corner registration crosses, a tick ruler along two edges, and the same square traced Repeat passes times, each pass starting from a different corner and alternating direction so backlash shows as a doubled line. Measure the sides for step calibration, the two diagonals against each other for gantry squareness, and the repeats for backlash. Unlike Test Card this node never scales to fit — a millimetre on the sheet is a millimetre, and a square that does not fit the canvas is refused with a printed warning instead of quietly shrunk. Origin cross draws an identical cross as the first and last stroke of the file: if the two do not land on top of each other the machine lost steps during the plot, which needs Optimize route switched off, since a nearest-neighbour sort sees two identical crosses as zero travel and plots them back to back. The square is on its own pen, every mark and label on a second.", tags: ["geometric","grid","text"] },
  "cardsheet": { t: "imposition for postcards and folded cards, both sides of the paper. A grid of cards (Card width/height, Columns, Rows, Gap, Sheet margin; cards that do not fit are dropped and the overlay shows the grid that did) is laid on the sheet and a full-canvas composition is scaled into each card face as in Mini Canvas — Scaling: Fit, Fill (crop), Stretch, Rotate 90 + Fit / Fill. Fold None gives a flat postcard with Front and Back pins; Vertical or Horizontal folds the card in the middle and the pins become Cover, Back cover and the two inside faces (Inside L/R or Inside top/bottom). The outside of a horizontal-fold card is laid out the way the paper works: cover on top, upside down, so it reads upright once the card is folded. Two-sided work runs through Side: plot Front (outside), turn the sheet, switch to Back (inside), plot again. The back layout is derived, never typed — the face behind each panel is its real partner (behind the cover sits the inside page you see when you open the card) and the sheet is mirrored according to Flip axis: Vertical axis for turning the sheet like a page (columns swap, artwork upright), Horizontal axis for turning it end over end (rows swap and everything turns 180°). Registration marks print at identical sheet coordinates on both sides and are symmetric under both flips. Three ways to nail the back to the front: Back offset X/Y shifts back-side content only (read it off the Duplex test); Trim frame draws one outline around the whole grid — cut the sheet to it after the front and the sheet edges become plotter-accurate, so the back registers against them; Pin holes marks two 6 mm hole centres on the flip axis in the waste margin for pin registration, which makes the paper's cut tolerance irrelevant. Mode Duplex test replaces the content with vernier scales at four points — front ticks 1.00 mm apart above the baseline, back ticks 1.10 mm below it; hold the sheet against the light with the back facing you and the pair that lines up, k ticks from the centre toward the arrow, means Back offset = 0.1·k mm on that axis. Trim marks, fold ticks or dashed fold lines and panel frames go on the Mark pen. Compare Zine (booklet imposition, page order by folds) and Mini Canvas (contact sheets and one-sided production runs).", tags: ["clip","combine","grid","repeat","structural"] },
  "carve": { t: "(deform) — parametric window t0..t1 of every path by arc length, with interpolated cut points. Wire Frame t into End t for a write-on animation; Invert keeps the complement, wrapping correctly on closed paths.", tags: ["animation","deform"] },
  "caustics": { t: "top-down shallow-water light caustics: the surface is a sum of crossing noise wave trains, brightness is its curvature (Laplacian), and the bright focus ridges are traced as marching-squares iso-contours stitched into flowing threads. Focus gain, brightness threshold, contour bands, ripple scale, depth stretch, minimum line length.", tags: ["nature","noise","terrain","water","wave"] },
  "cellular_mosaic": { t: "assigns points to lattice cells, splits paths at cell borders and displaces each fragment by its cell's seeded offset; optional sub-lattice quantize snap for a crystalline look. Duplicate points cleaned.", tags: ["deform","grid","repeat","warp"] },
  "chain": { t: "interlocking chain links drawn as flat hatched bands with real hidden-line removal. Each link is a closed ribbon lying in ONE plane, which is what makes the occlusion exact and cheap: the depth of a plane is a closed-form solve at any screen point, so where two links cross the one behind is cut away exactly and the over/under weave falls out of the geometry — there is no weaving bookkeeping in the node at all. Element picks the outline (Circle, Triangle, Square, Hexagon); Corner round is not decoration but a constraint, because the band is the centreline offset along its own normal and the inner edge folds over itself wherever the curve turns tighter than the half-width, so the rounding is clamped above it. Layout runs the chain along a line, closes it into a ring, or follows any paths wired into the Spine input. Alternate tilt is the character control: 90° gives a real chain with every second link edge-on, low values lay them nearly face-on as overlapping ellipses. Link spin turns each element inside its own plane and Spin / link adds to that per link; Offset staggers every second link sideways into a zigzag (both accumulate by index — a constant rotation or shift would only move the whole drawing and vanish in the centring). Hatch: Chevron, Chevron alternating (herringbone), Rungs, Diagonal, Cross. Link size is a true millimetre measurement — the fit shrinks and never grows — and Hatch spacing is in paper millimetres, so it survives the fit. At one link the chain parameters hide themselves and the node is simply a hatched ring or polygon band.", tags: ["3d","geometric","hatch","repeat","weave"] },
  "chipdie": { t: "a microchip die shot built the way a die is built. A seal ring and a ring of bond pads (nested squares) frame the edge; inside, the core is split hierarchically into blocks with routing channels left between them, and every channel carries a bus of parallel traces whose width shrinks with the depth of the split. Blocks take a texture from their type — SRAM as sub-arrays of dense word lines broken by bit-line groups with a decoder strip between, standard-cell logic as power-rail rows filled with cell edges, metal stubs and L-shaped routes, analog as interdigitated transistor fingers and a rectangular spiral inductor, capacitor arrays as a lattice of squares, IO as nested frames, empty silicon as sparse dummy fill — and routed blocks are the tangle of a 1970s die: thick Manhattan traces walked on a grid so they never cross, a via square at every end, as centre lines or outlined rods at Trace width. Style: Processor repeats one core's floorplan mirrored into every core slot under a row of L2 arrays and above an IO strip; Memory is banks of arrays with decoder logic; FPGA a uniform grid of tiles with a channel on every row and column; Analog a few large mixed-signal blocks (an inductor is guaranteed); Vintage one routed die with a wide power ring, a few transistor islands and big pads; Random a seeded floorplan of everything. Colour by type puts each class on its own pen counted up from Pen — seal and pads 0, SRAM +1, logic +2, analog +3, IO +4, buses +5, routing +6, modulo 12 — so a multi-pen plot reads like a false-colour die photograph; Bond wires arc from every pad out past the die edge (the die shrinks to leave them room). Every segment is axis-aligned. Die width and Aspect are exact mm, shrink-only; the Blocks output carries the closed block outlines on their pens for fill nodes.", tags: ["machine","grid","structural","texture"] },
  "chop": { t: "cuts paths into arc-length pieces (length ± variation, optional physical gap) and deals the pieces across 1–6 pens, cycling or randomly. Multi-colour within a single stroke.", tags: ["clip","pens"] },
  "chrono": { t: "Étienne-Jules Marey's chronophotographic motion analysis as a drawing: an articulated stick figure (head, trunk, both arms and legs with feet) is drawn at Frames successive instants of a motion — Long jump (approach run, take-off, hang, landing), Walk, Run, High jump, Standing jump or Somersault — with bone lengths held exactly constant, so the figures overlap the way superimposed exposures do. The skeleton is 3-D (sagittal joint angles on keyframe tables with Catmull-Rom interpolation, plus shoulder and hip widths), so View Side is Marey's plate and Front turns the camera round on the same model. Near limbs are solid and Far limbs Dashed as in the originals (Solid / Hidden); Frame style can dash alternate or early instants; Head Circle / Dot / None. Trajectories trace chosen joints (head, hip, hands, feet, or all) as smooth dashed curves sampled from the motion itself, with a marker at every instant and SFONT Numbers 1…N above them. Time window crops the motion to a phase range, Spacing scales the forward displacement (0 stacks every instant on one spot), Stride stretches the travel, Trunk lean tilts the figure. The ground is where the lowest foot stands: walking never leaves it, jumps lift off it, and Ground line draws it with Marey's end dot. The whole sequence is centred and fitted (shrink only) inside the margin box. Wire a line into Path and the pelvis follows it instead — the motion supplies the poses, the wire supplies the route. Animate turns the plate into an animation: Single instant draws one figure at Phase (wire the Frame clock's t into it), Onion skin adds the previous Onion frames exposures as ghosts (Onion style Dashed / Solid), and Trail lets the trajectories write on up to the current instant (so far / full / none) — the layout, scale and ground come from the whole time window, so the figure travels across a fixed sheet frame by frame. Pens: Figure, Trajectory, Labels.", tags: ["animation","creature","scientific"] },
  "circpack": { t: "non-overlapping circles grown by rejection sampling; size range and optional noise-weighted density.", tags: ["geometric","noise","round"] },
  "circuit": { t: "constructivist circuit compositions: solid blocks in aligned columns, orthogonal trace bundles between them, and a baseline the picture rests on. Blocks stack into Columns and every block in a column shares its width, so the stacks read as one structure. Traces leave block edges in bundles of parallel lines at Bundle pitch and turn at right angles — L routes turn once, Z twice — ending on another block, on the baseline, at the sheet edge, or in a short stub with a cross-tick. Routing is corridor-checked against the blocks with a clearance and a route that cannot be found is dropped rather than drawn through a block. Crossings either overlap plainly, as in the steel-wire originals, or cut Under gaps into the lower trace. Frames adds empty outlined rectangles as a counterweight to the black mass. A pen cannot lay solid ink, so block Fill is dense hatching (Hatch, Cross, Contour) and Fill spacing is in real paper millimetres — it sets the plotting time more than anything else here. Whitespace bias slides the block cluster sideways and leaves the other side to the long runs. Compare Diagram: that draws numbered nodes and arrowheads on a ring or grid; this has no arrows and no node identity, and hangs off a baseline.", tags: ["fill","grid","scientific","structural"] },
  "clockface": { t: "a clock dial without hands or numerals: hour batons around a circle (count is a parameter — 12 is a clock, 24 a day dial), minute marks between them (None / Dots / Lines, on their own pen), an optional spiral-dot center and a rim circle at an adjustable percentage of the radius. Each baton is a closed quad: Keystone tapers it (positive = wider at the rim, ±1 collapses to a triangle, like a classic radial baton) and Quarter scale enlarges the markers sitting on exact quarter fractions of the circle (12/3/6/9 on a twelve-hour dial). Outlines only — hatch downstream for solid batons. Diameter and center are value ports, so the dial can be driven.", tags: ["chart","geometric","hatch","spiral","text"] },
  "clouds": { t: "old-etching cumulus: each cloud is a row of overlapping lobe circles plus a few stacked on top, drawn as scalloped visible arcs. Inner creases lets each arc continue a little way behind its neighbour, like an engraver's line; Hatch shading adds horizontal rows that thin upward plus a dashed drop shadow under the flat base.", tags: ["hatch","nature","round"] },
  "cmyk_registration": { t: "prepress furniture as art: thirteen authentic registration and control marks (crosshair target, letterpress bullseye, GATF-style star target, Japanese tombo center/corner, Western crop marks, a CMYK color bar at real screen angles, slur ladder gauge, flexo eye-mark stack, quartered survey target, micro cross, bookbinding collation steps, graduated scale cross). Registration-color marks plot once per plate with seeded Misregistration (+ per-mark Wobble) for classic out-of-register ghosting; single-channel patches stay on their own plate. Mark checkboxes choose the population for the Grid/Ring/Border/Scatter layouts and filter the full Press sheet imposition arrangement; Single draws one mark at the canvas center chosen by the Single mark dropdown (Tombo corner and Crop marks place four oriented corner marks instead).", tags: ["geometric","grid","hatch","machine","round","scientific"] },
  "coil": { t: "replaces the line with a trochoid: overlapping loops when pitch < 2πr (cursive eee / phone cord), stretched waves otherwise; constant loop density thanks to arc-length sampling.", tags: ["decoration","spiral","wave"] },
  "collect_frames": { t: "the animation fan-out: wire a Frame-clock-animated branch in and every animation frame comes out as its own output (the engine frameFan seam re-evaluates the level once per frame with frameIdx 0..N-1 and frameCount = N — the Frames count here defines the frame domain, whatever the ANIMATE panel says). Evaluation cost multiplies by the frame count; one collector per dependency chain, and inside a Group the group's bound inputs arrive frozen at the outer frame.", tags: ["animation","combine","stack"] },
  "color_mesh": { t: "crumpled-paper facet field filled with fine cross-hatch mesh. The sheet is fractured into convex facets by random BSP cuts; each facet gets its own hatch angle (Angle + Angle spread) and a line-spacing gradient aligned to the global Light angle, so facets shade like folded paper. Facets take pens from a coarse noise field (First pen + Pens used, region size via Color patch), producing large coherent color regions. Mode 3D lifts every facet corner to a deterministic hash height (Relief) — shared cut vertices lift identically, so the surface never tears — interpolates facet interiors over centroid-fan triangles for sharp folds, bends the resampled hatch over them, applies true Lambert spacing modulation (facets facing away from the Light go denser; normalized so Relief 0 reproduces Flat line-for-line), then tilts the sheet (Tilt) and refits it to the margin box. Lines alternate direction per facet for efficient plotting; Outline draws facet borders, folded too in 3D.", tags: ["3d","clip","geometric","hatch","mesh","region"] },
  "comets": { t: "nucleus and sweeping tail. Detailed draws the ball with coma arcs and a fan of curved tail streamlines; Minimal is just a dot and a single line. Body and tail on separate pens; tails point away from the sun direction. Unlike Pins' order-to-chaos needle field, Comets is a few scene comets sharing one sun.", tags: ["chaos","flow","nature","pens","scatter"] },
  "concrete": { t: "text as image, using the built-in single-stroke font. Layouts: Fill region (repeating text rows clipped glyph-by-glyph to any closed shape wired into the Region input — a poem in the shape of anything), Spiral (text winds inward along an Archimedean spiral, letters rotated to the tangent), Wave (undulating baselines, letters lean with the slope), Scatter words (seeded dada scatter with size/rotation variation).", tags: ["clip","image","region","scatter","spiral","text"] },
  "conformal": { t: "the Smith chart and its relatives: a rectangular R × X grid pushed through a conformal map, so the grid lines curve into circle and arc families that stay orthogonal at every crossing. Map Smith is the impedance chart ((w−1)/(w+1), right half-plane onto the unit disc — constant-R circles tangent at the right rim, constant-X arcs through the same point), Admittance its mirror image through the centre, Immittance both together with the admittance grid on Admittance pen; Inversion 1/z, Joukowski (w+1/w)/2, Log-polar exp(w) and Power w^n (Exponent) map a symmetric source grid of Range with Major lines per range. Subdivision follows the printed chart: each major interval is split into Minor per major, each minor is halved Fine depth times, and a sub-level line is drawn only along the stretch where the gap to its same-level neighbour is at least Cell mm — fine hatching appears where cells are large and fades where they crowd; majors are always drawn whole. Every line is a polyline sampled by rendered length (Line step mm), so one code path serves every map. Clip Disc keeps the unit disc (Radius mm, shrink-only fit that includes the scale rings), Sheet lets the map run to the margin box, Wired shape clips to a wired closed path (Region pin). Smith dressing, all optional: Axis (horizontal axis and centre mark), Scales Angle (reflection-coefficient ring, ticks every 2°, numbers every 10°) and Wavelength (0–0.5 clockwise from the left, ticks every 0.002, numbers every 0.01), Labels (SFONT values on the majors: R vertical along the axis, X at the rim rotated radially; Label size, capped for small charts). Output is assembled coarse-first under the point budget, so a heavy chart loses its finest hatching before its skeleton. Pens: Major, Minor, Fine, Admittance, Scales, Labels. No randomness.", tags: ["geometric","grid","math","round","symmetry"] },
  "container": { t: "limits content to a region: wire any closed shapes into Region (the whole set acts as a union), or pick a built-in Rectangle, Circle or Triangle placed with Center/Size/Rotate — both parametric and wired regions show as dashed guides when the node is selected. Keep Inside boxes an effect into the area, Outside punches a hole; Gap grows (+) or shrinks (−) the region from its edge, cuts are bisection-accurate at the border and fully-inside closed paths stay closed. Draw region plots the container outline on its own pen; unwired Region passes content through. Content → Squiggle → Container confines every mark of an effect inside a Potato; Container first lets the wave overshoot the edge. Supersedes the deprecated Mask.", tags: ["clip","combine","region","round","wave"] },
  "contour_field": { t: "early-computer-art contour plot: a random height field sampled on a COARSE grid and contoured with straight-line interpolation, so the level lines stay hard-cornered and angular — nested angular diamonds around peaks, tight parallel bundles on slopes. Cells sets the coarseness, Roughness blends smooth terrain into independent random spot heights, and Edge numbers stamps each level's index where its line runs off the field, like hand-annotated 1970 plotter output (collision-avoided, own pen). Pens cycles levels across the palette.", tags: ["animation","chaos","pens","physics","scientific","terrain"] },
  "conway": { t: "Game of Life replayed deterministically from a seeded board for N generations per compute; wire a value into Generations to animate growth. Live cells drawn as squares, dots or diamonds, with optional edge wrap.", tags: ["animation","dots","scientific"] },
  "copypoints": { t: "instances the Motif input onto the Points input's path points (resampled at a spacing, or raw vertices): per-copy scale and rotation jitter, tangent-aligned or random rotation, keep probability, point budget.", tags: ["combine"] },
  "cracked_paint": { t: "peeling paint craquelure: a hierarchical crack network splits the sheet into flakes, early cracks wide dark gaps and later ones hairlines (Hierarchy), every crack noise-curved (Wobble), breathing in width and pinching to hairline tips. Horizontal bias steers the primaries. Wide cracks draw as varying-width outlines with lengthwise fill; Chips bulges dark blobs along the cracks and knocks small flakes out as hatched voids (own pen); Edge curl adds the lifted-flake inner line.", tags: ["connect","hatch","noise","organic","texture"] },
  "crop": { t: "clips to a rectangle (keep inside or outside), with bisection-accurate boundary points; fully-inside closed paths stay closed. Guide overlay.", tags: ["clip"] },
  "crossstitch": { t: "lettering for thread on paper. Text is set in a bitmap sampler font on a stitch grid; every filled cell is one cross stitch, and the cell's four corners are the holes the needle must pierce. The Holes output carries those holes once each as small circles at Hole size, deduplicated where neighbouring stitches share a corner (five stitches in a row are twelve holes, not twenty) — chain it into Needle Punch with Punch at: Centers, or plot the circles and pierce by hand. The Stitches output (the second pin, wire it separately) is the thread guide: an X per cell, a Half / or Half \\ stitch, a Backstitch outline round the letters (every cell edge with a stitch on one side only), or None — the holes never change with it. Font Sampler 5x7 is the classic, Bold 5x7 thickens it by one cell, Tiny 3x5 is for small work; all carry A–Z, 0–9, ÄÖÅ and punctuation, and <3 is a heart. Pitch is the physical hole spacing and stays exact unless the block cannot fit, when it shrinks; the hole radius is capped below half the pitch so holes never merge. Letter gap and Line gap are whole cells, Border adds a one-stitch frame at Border gap, Mirror flips the block for punching from the back, separate pens for holes and guide.", tags: ["text","dots","grid","weave"] },
  "ctrl": { t: "turns live input into graph values. Layout picks what drives the outputs. Channels is the generic 1-6 set nudged by the arrow keys or driven by gamepad axes. Sticks gives four pins — LX and LY from the left stick, RX and RY from the right — so each stick reaches two parameters at once. D-pad + triggers gives Pad X, Pad Y, L2 and R2: left and right step Pad X down and up by D-pad step, up and down do the same to Pad Y, and the two analog triggers land on their own pins — a stepped pair for exact increments beside a pressure-sensitive pair for sweeps. Both d-pad directions act on the rising edge, so holding the pad does not run the value away. Every channel, in every layout, is stored NORMALISED 0-1 in v1..v6 and mapped into Out min..Out max with optional Snap. That one storage model is why the range, the snap, the keyboard nudge and the panel readout are the same code for a stick axis, a d-pad step and a trigger — and why the values save with the patch and replay identically on export. (The inspector rows stay CH1..CH4 in the named layouts because parameter labels are static; the pin labels and the LIVE panel show the real names.) Axis mode Absolute maps stick position straight across the range, while Jog integrates deflection over time so a self-centring stick behaves like an endless jog wheel — push and the value travels, let go and it stays. Source Keyboard drives the ARMED Controller in any layout: ↑↓ nudge the active channel, ←→ pick it, Shift is coarse and Alt fine. A Controller stays armed while you go on to select and preview other nodes, which is necessary because the big preview only opens on a node that outputs paths and a Controller never can; with it open a compact readout mirrors the channels above the overlay. Binding overrides the pad index and, in Channels, the axis mapping; `auto` takes the first CONNECTED pad rather than slot 0. Freeze stops all live writing so a tuned value stays put. Wire a channel into any value port.", tags: ["animation","math"] },
  "cull": { t: "(penout) — drop paths by criterion: Random keep-probability (seeded), Every Nth, or Shorter/Longer than a length, with Invert.", tags: ["pathops","penout"] },
  "cycloidm": { t: "simulation of the classic wooden drawing machine: two cranks, two linkage rods, the pen at the rods' circle-intersection, paper on a slowly rotating table. Continuity-safe branch selection; auto-fits to canvas.", tags: ["machine","physics","plants","round"] },
  "dazzle": { t: "WWI razzle-dazzle: recursive straight-chord splits carve the sheet into convex patches; each patch gets hatching at a quantized clashing angle (never repeating its neighbor), with blank, cross-hatch and wavy patch styles, and optional bold outlines. Serpentine stripe order.", tags: ["fractal","geometric","hatch"] },
  "delaunay": { t: "triangulation of input path points (resampled or raw vertices) or seeded random sites; the dual of Voronoi. Shared edges emitted once. Feed any artwork in for a low-poly version.", tags: ["geometric","mesh"] },
  "diagram": { t: "flow-diagram generator: numbered circle or square nodes joined by directed orthogonal arrow lines (L/Z routing with node avoidance). Line styles: thick filled arrows (outline + parallel fill + solid head), thick outline, or a single line with a V head. Crossings Under cuts a clean gap into the lower line where another passes over; corners Rounded / 45° / 90°. Node and line pens separate.", tags: ["animation","chart","clip","flow","pens","structural"] },
  "dice_pips": { t: "classic dice faces. Single draws one face; Sequence reads values such as `1-6`, `0 2 4 6 8` or `987` and lays them out as a centred grid that shrinks to fit the sheet. Values 1-6 are the standard die faces, 0 and 7-9 conventional domino-style extensions on the same 3x3 grid. Pips only, or a square, rounded-square or circular frame on its own pen. Rings and Spiral fill turn each pip into a solid plotter dot — set Fill pitch to suit the nib.", tags: ["dots","fill","geometric","grid"] },
  "diffgrowth": { t: "the classic organic-growth algorithm: a seed circle whose points repel neighbours and split stretched edges until the line fills space like coral. Deterministic (position-hashed chaos); wire Iterations to animate. Heavier at high iteration counts.", tags: ["animation","chaos","organic","round"] },
  "diffpens": { t: "compares Modified against Original and recolors only what changed: paths present in both keep their pen, anything NEW in Modified moves to the Diff pen. Feed a sprig to Original and the same sprig through Fur to Modified — the sprig stays one color, the fur gets another. Exact match is fast for add-only modifiers; Distance match tolerates wobble and splits (Hand Drawn) within the tolerance.", tags: ["combine","pens"] },
  "displaceimg": { t: "(deform) — a loaded raster (fileImage) displaces paths: darkness pushes along a chosen angle, or the darkness gradient makes lines flow toward tonal edges (emboss). Untouched passthrough when no image is loaded.", tags: ["deform","flow","halftone","image","warp"] },
  "double_pendulum": { t: "a real double pendulum drawing its chaotic trace (RK4, fixed step, fully deterministic — no seed). Trace Bob 2 / Bob 1 / Both / Midpoint; Traces runs up to eight pendulums with a tiny Perturb offset so chaos tears the bundle apart, optionally one pen per trace. Damping spirals the line into rest for a finite drawing; the trace provably stays inside Arm 1 + Arm 2 around the Pivot. Chain into Brush Z (Ramp down) for a chaotic brush stroke fading with the energy.", tags: ["chaos","physics","scientific","spiral"] },
  "drape": { t: "a mesh cloth laid over hidden objects, drawn in 3D with true hidden-line removal. Seeded spheres, boxes, cones or a mix sit on a table; a grid sheet is dropped over them and relaxed with Tension until it rests on the tops and sags between them (each pass averages a point with its neighbours but never lets it sink below an object; a little gravity stops it floating flat), and Wrinkles folds only the raised cloth. Wire your own objects instead: closed paths on the Objects input become flat-topped blocks with a soft edge, open paths round ridges, and a triangle mesh on the Mesh input (Blob Mesh, or anything Mesh Slice takes) is rasterised from above into the height field — a wired input replaces the seeded objects. Yaw, Elevation (90 = straight down, where the grid is an exact lattice) and Perspective turn the view; a screen-space z-buffer hides the far side of every bump, and a low view hides more than a high one. Style: Wire, Weave (warp and weft break alternately at every crossing), Contour (height contours of the draped surface projected in 3D, with the rim and a sparse table grid) or Hatch (grid lines that survive only away from Light angle, plus the silhouette). Sheet Fit is a rectangle in the margins' proportions, Square a square, Round a disc whose outline does not change with Yaw at all. Lock size scales by the sheet's rotation-invariant bounding circle so turning never changes the scale; off, the drawing refits the margins at every yaw.", tags: ["3d","mesh","grid","weave"] },
  "echo": { t: "(deform) — 1-12 progressive copies where translate, rotate and scale compound per copy; pivot at canvas center or path centroid; optional pen cycling per echo.", tags: ["deform","pens","repeat"] },
  "empty_fill": { t: "fills the EMPTY space around the input shapes with a repeating texture: the doodle trick where stones stay blank and everything between them gets dense pattern. Closed paths block by area, open paths by proximity (chamfer distance field). Patterns: Coils (overlapping occluded circles — the slinky look), Contours (distance ripples hugging every shape, marching-squares chained), Scales, Hatch, Crosshatch, Waves. Gap keeps a clean clearance ring, Wobble adds hand-drawn waviness, Angle rotates the texture. Feed it Potato or Pebble blobs for the classic stone-doodle page.", tags: ["fill","hatch","pens","spiral","terrain","texture"] },
  "endcaps": { t: "arrows, dots, circles or ticks at open-path ends (start/end/both), oriented by the path's final direction. Flow Field's missing arrowheads.", tags: ["decoration","dots","flow","round"] },
  "eraser": { t: "erases a region: everything inside the zone (rectangle or circle, dashed guide when selected) is removed and crossing paths are cut cleanly at the border. Invert keeps only the inside instead — a circular or rectangular crop for any geometry. Gap grows (+) or shrinks (−) the erased area from its edge, so a positive gap leaves breathing room at the cut. Closed paths that get cut reopen as arcs.", tags: ["clip","plants","region","round"] },
  "explosion": { t: "rigid per-shape translation (shapes keep their form). Blast from a point (Outward/Inward with distance falloffs) or Directional at a fixed angle; effect limited to a circle or rectangle zone, and in rectangle mode movement can be constrained to the horizontal or vertical axis only. Jitter + angular spread keep it organic. Guide overlay with arrows.", tags: ["clip","region","round"] },
  "fabric": { t: "warp and weft lines deformed by one shared displacement field (so the weave stays coherent): Curtain folds deepening downward with sag, Flag traveling wave, Silk pure noise flow; plus fine rumple.", tags: ["flow","noise","organic","warp","wave","weave"] },
  "fadeout": { t: "comet tails by lifting the pen SLOWLY while it still moves: the ink starves and the stroke fades out. Encodes a negative Z (lift above pen-down) into the point third component; the export turns it into simultaneous Z moves (bed-Z only, ±6 mm clamp, capped at pen-up — needs the 2.42 export patch). Fade length ramps the lift inside the stroke's last millimetres, Tail extension continues past the end along the exit tangent; ramps Linear / Soft / Long (the pen hugs the paper and lets go late — longest visible tail) / Quick. End / Start / Both, seeded per-stroke Variation; short strokes and closed paths pass through. MUST be last in the chain, like Brush Z. Note: Travel Sort may reverse strokes, turning a fade-out into a soft landing.", tags: ["penout","region"] },
  "fan": { t: "duplicates one value to several outputs with per-output offsets — one knob driving many parameters.", tags: ["math","repeat"] },
  "fingerprint": { t: "fingerprint ridges: evenly spaced rings grow from seeded centers and MERGE where systems meet — contours of a soft-min distance field, so the gap between neighbouring lines stays constant everywhere. Merge sets the fusion softness (0 kissing circles, 1 one big swirl), Wobble warps the ridges loose, Max rings leaves white pools, and Line breaks + Gap dots cut the ridges like a drying pen with ink dots dropped into some breaks. Heavier than average — lower Centers or raise Ring gap while sketching.", tags: ["dots","image","organic","plants","terrain","tiling"] },
  "fish": { t: "line-drawn fish in two hands. Style Simple is a child's fish: a lens body and a triangle tail as one closed path, one big eye (sometimes in the wrong place), a smile, an o or a line for the mouth, 0–2 triangle fins, a few U-shaped scales, stripes and bubbles, every stroke shaken by Wobble % so it reads as crayon rather than geometry. Detailed is a naturalist's ink drawing built by a skeleton walk: a Species body profile (Perch, Pike, Roach, Bream, Burbot, Trout or Generic — Finnish lake fish) with a snout arc whose bluntness is species-specific, rayed dorsal, anal, pectoral and pelvic fins (the perch's front dorsal is spiny and tallest at the head), a forked or rounded caudal fin with rays, gill cover, lateral line, eye with pupil, mouth (Mouth Open drops the lower jaw from its hinge) and species markings — perch bars, pike spots, trout dots, burbot mottle — plus crescent Scales on a staggered grid whose density follows Detail %. Mixed rolls the style, and Species Mixed the species, per fish from the seed. Layout Rows fills a Count x Rows grid loosened by Jitter %; School scatters a shoal swimming toward Heading with Turn jitter; Spine strings fish along a wired path facing its travel direction, Spine mount either On path or offset Left, Right, Both (alternate) or Both (random) on the Fur convention; unwired, a horizontal line through the centre. Fit is shrink-only: every fish is measured after placement and reduced to its cell or the Margin, never enlarged, so Size stays a size. The Bodies output carries each fish's closed body-and-tail silhouette, identical to the one in Lines, for fill and hatch nodes. Decoration is emitted last, so a point-budget cut removes scales before it removes fish.", tags: ["creature","nature","water","repeat"] },
  "fit_canvas": { t: "scales and centres content into the margins: contain, stretch, fit-width or fit-height. The \"fix my composition\" node.", tags: ["transform"] },
  "flash_distort": { t: "the lightning-bolt poster cut: slices everything into parallel strips and slides each strip along its own direction. Angle rotates the whole cut, Segments + Widths (Uniform/Random/Ramp/Wave) shape the strips, Shift pattern picks Alternate (the classic zigzag), Ramp, Wave, Random or Walk with Jitter on top. Cuts are exact; Close cut faces clips closed shapes into per-strip closed polygons (new edges along the cuts) — feed those into Hatch Fill for the filled flash-stripe poster. Guides show the cuts.", tags: ["chaos","clip","deform","hatch","region","wave"] },
  "flow": { t: "streamlines traced through a noise vector field. Scale sets feature size, steps set line length. The classic organic-flow workhorse.", tags: ["flow","noise","organic"] },
  "flow_traces": { t: "circuit-atlas routing: strictly self-avoiding traces walk an orthogonal grid steered by a flow field — Flow angle plus Swirl around the canvas center plus Wave (periodic side-urge that turns runs into square-wave detours) plus Turn bias. Every lattice point is used at most once, so nothing touches or crosses (validated). Corners are exact arcs; ends get terminals (Dots double rings, Rings, Pads, None) with the centerline trimmed back clear of its own terminal. Sibling of PCB Tracks — that one is octilinear copper with pads, this one pure orthogonal flow.", tags: ["dots","flow","grid","round","structural","wave"] },
  "fmrose": { t: "FM synthesis as a polar curve: a modulator warps the carrier that shapes the radius. Low index gives rosettes, high index chaotic flowers; Rings stacks scaled copies with per-ring rotation, and Ring pens cycles successive rings through that many pens.", tags: ["chaos","geometric","pens","repeat","warp"] },
  "fold": { t: "(deform) — a wavefolder for geometry: points beyond the window reflect back inside, repeatedly. Gain drives the shape outward before folding, exactly like input gain on a synth wavefolder, multiplying the creases.", tags: ["deform","warp","wave"] },
  "followlines": { t: "the \"follow the previous stroke\" marker technique: iterative offsets whose distance varies along the length (Drift), so bundles pinch into dense ridges and fan into light sheets; Relax straightens successive lines. One-sided or both; multiple generated wave bands, or wire any curve as the Spine.", tags: ["organic","wave"] },
  "fourier": { t: "(deform) — elliptic Fourier reconstruction of closed shapes from the first K harmonics: K=1 is an ellipse, K=64 the original. Wire a value into Harmonics to morph detail in over an animation; optional epicycle ghost circles.", tags: ["animation","audio","deform","region","round"] },
  "frame": { t: "the animation clock. Outputs: `t 0→1` linear ramp (last frame = 1), `frame #` integer, `wave loop` and `ping-pong` (seamless: frame N continues into frame 0). Reads the ANIMATE panel's frame state — or a frameFan collector's frame domain when one drives the graph. A fifth output `rot °` gives a loop-seamless rotation in degrees, (frame / frameCount) · 360, for wiring straight into Rotate inputs.", tags: ["animation","chart","math","wave"] },
  "frame_grid": { t: "animation frame imposition: frames land in a grid on one sheet with photo_trace-compatible fiducial markers (hatch-filled squares, centers exactly 20 mm from the corners, top-left orientation hole) so a camera pipeline can homography the frames back out. Fill Animate (default) takes the WHOLE animation through one input via the frameFan engine seam: Total frames defines the frame domain (the upstream Frame node sees frameCount = Total), and overflow pages onto further sheets — the outer ANIMATE frame is the SHEET index, so set panel Frames = ceil(Total / cells); per-frame export writes one file per sheet, numbering runs globally and a P n/N tag lands bottom-right. Fill Inputs gives one pin per cell (Sheets-shaped, one plot); Clock places a single input into cell frameIdx for per-frame export merging. The whole canvas maps into every cell with ONE shared scale so frames stay registered; Fit each is the contact-sheet alternative. Cell frames, frame numbers, a Label line and a marker pen complete the sheet. Evaluation cost multiplies by Total in Animate.", tags: ["animation","combine","grid","machine"] },
  "frame_split": { t: "chops ONE drawing into animation frames: N outputs that wire straight into Frame Grid. Split by exact Ink length (paths cut mid-stroke at the arc position, a z component interpolates through) or by whole Path count in draw order; frames Build-up cumulatively (the plot draws itself — the last frame is the whole piece) or hold disjoint Windows; Ease curves the boundary spacing and Reverse un-draws from the end. A closed path stays closed only once fully inside a frame.", tags: ["animation","combine","pathops"] },
  "fray": { t: "loose threads fraying off the source line, like yarn ends pulled out of an embroidered outline: strands leave the path at Spacing intervals (Spacing jitter), head Outward — or Left / Right / Both / Alternate for open lines — within Spread of the normal, wave with Wave amp / Wave length, Wander off course and lean toward the Drift angle by Drift; lengths scatter by Length variation (most short, a few long) and stop at Margin when Clip to margin is on. Along the way Hitches tie small self-crossing loops and Beads hang tiny rings; every thread ends in a Coil (loose overlapping loops), a Ring, a Knot (tight tangle), a Mix, or None (frayed tip) at Coil size ± Coil variation. Each thread is ONE continuous stroke from root to coil end. Avoid source keeps threads, beads and coils off the interior of closed shapes. Crossings None makes the whole result crossing-free: coils turn into inward spirals, hitches vanish, beads move beside the thread, and threads steer around or stop at other threads and the source (spatial-hash segment test). First pen + Pens used picks a seeded colour per thread; Inherit source pens uses the root path's pen. Keep source passes the input through.", tags: ["decoration","deform","organic","texture"] },
  "fresnel": { t: "lens refraction that resets per concentric zone, exactly like a real Fresnel lens: within each groove the radial mapping is monotonic (no folds), and the groove boundaries produce the characteristic concentric shear discontinuities. Circular or linear (sheet-lens) mode, groove pitch, smooth-lens or prism profile, edge falloff; overlay shows the lens and a few grooves.", tags: ["fill","region","round","warp"] },
  "fur": { t: "short hairs along the path edge: spacing, length ± jitter, angle jitter, side (left/right/both alternating or random).", tags: ["decoration"] },
  "galaxy": { t: "a spiral galaxy as a rotatable 3D point cloud, deterministic from Seed. Stars sets the dot count, Arms and Twist wind logarithmic spiral arms with Arm spread scatter, Bulge % / Bulge size fill the core with a 3D gaussian ball, Thickness sets the disc depth and Halo % sprinkles a sparse spherical halo. Three pens make it multicoloured: Core pen (bulge + halo), Arm pen (disc), and Sparkle % of arm stars on Sparkle pen slightly enlarged — young clusters along the arms; Core glow enlarges dots toward the centre. Colors Extended adds three more pens — Halo pen separates the halo from the bulge, Inner disc % + Inner disc pen split the disc across a dithered blend zone, and HII regions % re-tags arm stars as star-forming knots on HII pen drawn 1.5× — six pens in one galaxy, while Classic (3 pens) keeps the original output byte-identical. Yaw / Pitch rotate in 3D (pitch 90 face-on, 0 edge-on), Perspective foreshortens, and scaling is rotation-invariant, so wiring the animation Frame into Yaw orbits the galaxy without size jumps. Dot shape: Circle (small ring), Dash (a stroke streaking along the galactic rotation — star-trail look) or Point (0.1 mm pen poke).", tags: ["3d","dots","scatter","space"] },
  "gcode_in": { t: "imports G-code back onto the canvas — the return leg of the Muusia → Latu → Muusia roundtrip, and a general importer for foreign plotter G-code. With everything on Auto, Muusia's own output returns 1:1: the header comment gives canvas/origin/Y-flip for an exact inverse transform, CHANGE PEN comments map to pen layers, closed paths are reconstructed, drawing order is preserved and Brush Z immersion returns to the points' third component (Brush Z: Keep/Ignore). Pen detect: Auto reads SET_SERVO angles or standalone bed-Z moves in context (contact after a travel, lift after drawing — z-hop travels stay lifted); G0 travel / G1 draw and Z threshold cover foreign files. Layers: Auto (pen comments), Split at pauses, or Single pen. Coordinates: Auto (header), As written, or Flip Y (content-box mirror for Y-up foreign files). Placement: True scale with Offset X/Y nudges, or Fit to margin. Understands G90/G91, G20/G21 and G2/G3 arcs (IJ and R forms, tessellated at ~0.5 mm); dips, maintenance blocks, Latu's INK_DOSE/AIR_PULSE/E words and other macros pass through as non-motion. Simplify drops points closer than the given pitch. Deterministic — no seed.", tags: ["machine","penout","pens"] },
  "girih": { t: "Islamic star patterns by Hankin's method: rays leave every tile-edge midpoint at a contact angle and weave a continuous star-and-polygon lattice over a hexagon or square tiling. One angle slider (54 deg classic) morphs the family.", tags: ["geometric","grid","tiling","weave"] },
  "glitch": { t: "segment displacement/slicing artifacts.", tags: ["deform","warp"] },
  "glitch3d": { t: "throws the drawing into 3D space and corrupts it: the sheet undulates with noise relief, tilts with yaw and pitch under perspective, then glitches in screen space — horizontal bands tear loose and shift sideways, some quantizing into blocky steps. Color split adds a displaced duplicate on another pen (plotter chromatic aberration). Wire Drift to Frame and the corruption crawls through an animation.", tags: ["3d","animation","deform","repeat","warp","wave"] },
  "glitch_loom": { t: "slices paths at horizontal loom rows and shifts each row by a seeded warp offset (clamped to the sheet); torn ends may spawn frayed threads that drip downward. Pitch, max shift, fray probability and length.", tags: ["deform","warp","weave"] },
  "glyphtone": { t: "a designer's halftone: each grid cell renders its darkness as a glyph — filled dot, donut ring, mini-dot cluster, stripe stack or stacked chevron (checkboxes). Source is a seeded noise field or an imported image (PNG/JPG, fitted to the margin box). Type by Value assigns glyphs by darkness band, Random picks freely; Big cells merges 2×2 giants for scale contrast; Pens used sprays glyphs across pens. Fill pitch is the concentric-fill spacing — match it to the pen width for solid blacks.", tags: ["dots","halftone","image","pens","scatter","text"] },
  "granulate": { t: "(deform) — granular synthesis for paths: the line is chopped into grains that each get jitter, rotation and scale, dissolving geometry into a cloud of its own fragments. Density thins the cloud.", tags: ["deform","texture"] },
  "gravity": { t: "a regular grid of stamps lets go from the bottom up: rows below the Release line detach, fall and pile into a heap on the floor of the margin box while the top of the grid stays intact — the falling-dots print. Stamp is a Dot, Ring, Square, Diamond or Cross, or the wired Stamp paths normalised to a unit box and repeated in every cell (Stamp size × cell; a Lettering glyph, a leaf, anything). Release sets how much of the sheet has let go, Softness blurs the line with a hashed term, Clumps adds a noise2 field that frees clusters higher up. Every released element gets a hashed fall fraction: Progress is the share that has already landed, the rest hang mid-fall skewed toward \"just let go\"; along the fall Drift moves them sideways with noise, Spin rotates them (hashed direction, shows on non-round stamps), Size mod shrinks or grows them — Spin / size apply to makes those two ramp with the fall (Fallen only) or gives every element, intact ones included, its own hashed spin and size (All) — and Grid jitter shakes the intact elements near the line. Pile Heap drops the landed elements in seeded order into a 1-D height field that rolls to the lower neighbour like sand (Pile spread pulls landings toward the middle for a central mound, Packing sets the stacking density), Floor lays them on the floor line, None lets them fall off the sheet. Palette 1–4 pens assigned by Diagonal (the i + j pattern of the classic print), Rows, Columns or Random — the colour travels with the element into the heap. Release 0 is the exact grid; the Seed moves only the released elements and the jitter. Guides show the margin box, the grid and the floor line.", tags: ["grid","dots","physics","scatter","noise"] },
  "gravity_cascade": { t: "particles launched into a field of gravity wells trace decaying orbits. Wells layout places the attractors (Triangle, Line, Ring, Center + ring, Random with a Wells count); Launch picks the start (Ring around the center, Top rain from the upper edge, Spiral). Paths end at the sheet edge.", tags: ["chaos","physics","round","scientific","spiral","water"] },
  "grid": { t: "vertical/horizontal line grid. The plain sheet of paper of generative art; feed it to Warp, Stretch or Lens to bend space itself.", tags: ["geometric","grid","warp"] },
  "group": { t: "a subgraph in a box (created with Cmd+G); double-click to enter.", tags: ["combine","engine"] },
  "growth": { t: "differential growth: a loop that grows (random edge splits + long-edge splits) while short-range repulsion keeps it self-avoiding and cohesion keeps it smooth — the organic meander classic. Circle or canvas bounds (guide overlay), optional history rings every N iterations for the nested look. Point-capped.", tags: ["organic","round"] },
  "gull_tracks": { t: "seagull footprint trails on wet sand: seeded walks that steer themselves back inside the margin box, steps alternating left/right at Straddle width, each webbed three-toe print turned slightly inward (Toe-in) like the real bird. Every print is unique — Variation jitters toe angles, lengths, curvatures and the web attach points per print (0 = identical stamps). Web sag pulls the webbing toward the heel; Hind toe adds the tiny rear hallux mark. Several nodes at different Foot sizes reads like a whole flock came through.", tags: ["connect","creature","nature"] },
  "gyroid": { t: "the triply periodic minimal surface sliced into stacked contour rings with the Retro Mesh camera (Perspective, Rot X/Y, fit). Cells sets the period count, Iso slides through the level-set family, Warp bends the field with seeded noise, Shape clips to Cube / Sphere / Cylinder. Surface Transparent overprints retro-style; Solid ray-marches the implicit field for exact hidden lines — front shells occlude the back while the holes still see through — with framing shared between the two so toggling never rescales.", tags: ["geometric","mesh","retro","terrain","weave"] },
  "hairs": { t: "area fill of short curved hairs. Direction: noise flow / fixed angle / radial; curl with random handedness; gravity droop. Optional Region input: wire closed shapes (Text outlines, silhouettes) and hairs grow only inside (even-odd).", tags: ["flow","noise","organic","physics","region","text"] },
  "halftone": { t: "dot/pattern shading driven by a noise field.", tags: ["halftone","noise","scientific"] },
  "handdrawn": { t: "makes any line look drawn by hand: smooth low-frequency wobble along the stroke's arc length, fine tremor on top, optional ink breaks (the pen skips), and end overshoot / fall-short so strokes don't stop exactly where they should. Every path wobbles differently, so parallel lines live like a real sketch. Unlike Jitter (raw point noise), the wobble follows the stroke itself.", tags: ["deform","noise"] },
  "hands": { t: "anatomically proportioned arms and hands, each drawn as one closed silhouette. The construction is a skeleton walk rather than a morph of stock shapes: a palm with five jointed finger chains on anthropometric phalanx ratios, knuckles set on an arc, and a forearm about 1.6x the hand length tapering from elbow to wrist. The outline is traced once around that skeleton — up the arm edge, around the thumb, finger by finger through the webs, back down the far edge and across the cut end — so every hand is a single closed path and routes, hatches and transforms downstream like any other outline. Pose picks the shape: Relaxed, Spread, Point, Pinch, Claw, Wave, Flip the bird, Rock horns, Half heart, or Mix, which rolls a different pose per hand from the seed; Pose jitter, Spread, Wrist bend and Elbow bend vary it further, and Which mirrors the whole thing between a left and a right hand. Mutation % slides from believable anatomy toward AI-hand chaos — joints past their physiological limits, knuckles off the arc, and past roughly half way fingers that duplicate, vanish or cross — while Detail % sets outline point density on its own, so angular low-poly and smooth-but-deformed are independent choices. Arm length (Hand only / Forearm / Full arm), Arm width, Cut end (Flat or a rounded Cuff) and Nails finish the anatomy, and Size scales the whole unit. Layout Rows lays Count x Rows hands onto a grid loosened by Jitter %; Layout Spine takes a wired path, where Spine mount either runs the arm Along it with the hand at the far end, or sprouts hands perpendicular at Spacing mm intervals — Left, Right, Both (alternate) or Both (random). Left and Right follow the path's travel direction, the Fur convention, not the screen: a spine drawn left to right puts Left above it.", tags: ["creature","grid","organic","repeat"] },
  "harmonograph": { t: "the classic twin-pendulum drawing machine: two damped oscillators per axis trace one continuous stroke that spirals inward as it dies. Near-integer frequency ratios plus a small detune give the iconic almost-closing loops.", tags: ["chaos","physics","scientific","spiral","wave"] },
  "hatch": { t: "fills closed shapes with hatching (angle, spacing, inset from both edges with parity checking); Outside region mode inverts via a synthetic frame ring.", tags: ["fill","hatch","region","round"] },
  "hersheytext": { t: "single-stroke plotter typography: built-in geometric uppercase font (A–Z 0–9 ÄÖÅ punctuation), `|` for new lines, size = cap height, tracking, line height, alignment, canvas centring. Every letter is pen strokes, not outlines.", tags: ["text"] },
  "himmeli": { t: "the traditional Finnish straw mobile in 3D: octahedral straw units built into classic forms — Single crystal (nested at higher complexity), Column (units tip to tip on threads), Chandelier (center with hanging side units), or Cluster (a two-layer cloud with pendants swinging on seeded thread lengths and angles). Rotate with View yaw and pitch; wire Frame into Yaw and the mobile spins through the animation. Shared straws are deduplicated.", tags: ["3d","animation","structural"] },
  "hyperbolic_truchet": { t: "Truchet arcs on a polar grid whose rings crowd toward the center or the rim (Ring Crowding), so the maze reads as a hyperbolic disc. Arc strands connect seamlessly across cells; Solve traces the strand network and recolors one strand running from the center to the outer rim onto the Solve pen (arcs style only).", tags: ["connect","geometric","grid","maze","pens","tiling"] },
  "image": { t: "raster import (PNG/JPG, downsampled to grayscale). Render modes: Scanline wave (darkness raises amplitude and frequency of horizontal waves), Halftone dots, Hatch levels (four cross-hatch passes gated by darkness), Flow shade (noise streamlines seeded and lengthened by darkness), and Contours (trace) — 1-6 tonal threshold levels traced as vector contour lines with a minimum-contour speck filter (the former Trace Image node, merged in 2.51; gamma, strength, cutoff and seed have no effect in this mode). Gamma, invert, white cutoff.", tags: ["dots","flow","halftone","hatch","image","terrain"] },
  "image_rasterise": { t: "true CMYK halftone separation of a loaded photo: each plate plots with its own pen at its own screen angle (the Angles select's Standard 15/75/0/45 is a one-click reset; Custom frees the four sliders). Dot styles: Dots (circles sized by density), Rings, Spiral (ink-coverage spirals) and Dashes (a cheap line screen for large sheets). Press-defect controls — Misregistration (seeded per-plate shift), Plate skew, Dot gain, Doubling (slur ghosts) and Ink noise — turn calibration into art. Black (GCR) sets how much gray moves to the K plate; Cell is the raster pitch (raise it if the point budget truncates — plates draw K first so a truncation eats yellow). Requires the 2.61 rgb image intake; photos loaded by older builds fall back to a grayscale K-only separation until re-loaded.", tags: ["dots","grid","halftone","image","spiral"] },
  "image_underlay": { t: "shows an image behind the preview without ever plotting it — a tracing reference for drawing over a physical print. Without calibration the image fits the margin box; with Calibrate on, jog the machine so the laser dot hits 2-4 corners of the physical print, type each DRO X/Y reading into its anchor, and a least-squares similarity fit (position + rotation + uniform scale) lands the on-screen image exactly where the print lies on the bed (laser offset and canvas origin from the machine profile). Per-anchor residuals draw as red arrows — a long arrow means that reading is off. The Frame output is the image outline as a closed path for region/containment masking. Uses the 2.51 bgImage engine seam; the photo travels inside the patch.", tags: ["image","region","text"] },
  "ink_burst": { t: "a decalcomania squash print: dense radial filaments around a blank core void, bent together into suction channels by a coherent noise field and torn into lens gaps by Breakup; beyond the body, Tendrils launch outward with long-tail lengths (Reach), curl as they go, and each ends in an ink droplet drawn as the SAME continuous stroke — stem flows into an inward spiral fill, one pen-down per tendril. Beads dot the stems, stray blobs spatter the mid ring, Aspect ovals the burst, Edge roughens the outline. Loves a thick pen.", tags: ["noise","organic","round","spiral","warp"] },
  "ink_relief": { t: "finds the places where the pen inks the same spot over and over and thins them out, leaving the rest of the drawing alone. Two kinds of pile-up get detected. Corners: nested rings from Offset or Morph Layers all turn at the same vertex, the pen decelerates to a near stop each time and a ballpoint leaves a glossy bead — Round replaces the corner with a fillet so the pen never stops, Fan pushes the stacked corners outward along the spike by rank, Notch cuts a gap so no ink reaches the corner at all. Overlaps: where a shape pinches, dozens of rings collapse onto the same straight run and one line gets drawn thirty times — Spread offsets each run perpendicular by rank so a black bar becomes a band of separate lines, Thin keeps every Nth pass and cuts the run out of the others, Taper cuts most from the middle of the stack and nothing from the outermost, hollowing the bar while keeping its silhouette. Relief scales with how crowded each pile is (Min passes, Full strength at), so a stack of thirty gets the full Amount and a stack of six barely any. Target Both runs the corner pass first and looks for overlaps in its result, which is stronger than either alone because the edges feeding a spike are themselves near-parallel. Show hotspots draws each pile on its own pen — circles for corners, a line along the run for overlaps — which is the fastest way to check detection before committing a sheet.", tags: ["deform","texture"] },
  "interference": { t: "marching-squares contour lines over fBm terrain or wave interference; segments are chained into long polylines.", tags: ["organic","terrain","wave"] },
  "jitter": { t: "per-point random displacement (densifies first).", tags: ["deform","warp"] },
  "joinends": { t: "connects nearby path endpoints into longer polylines (distance × angle scoring, rounds of batch pairing, optional same-pen-only). Run before export to reduce pen lifts.", tags: ["connect","pathops"] },
  "julia": { t: "escape-time fractal contours of the Julia or Mandelbrot set, banded by normalized iteration count. The c-parameters accept value wires, so an LFO turns the fractal into a living, loop-seamless organism.", tags: ["fractal","geometric","terrain"] },
  "kaleidoscope": { t: "(deform) — clips the source to one wedge around the canvas center and replicates it N times, mirroring alternate copies. A mandala from anything.", tags: ["clip","deform","repeat","symmetry"] },
  "kierto": { t: "rotates content around a point.", tags: ["transform"] },
  "knottube": { t: "a closed 3-D knot swept into a tube and drawn as counter-wound helices with real hidden-line removal, so the far side and everything passing behind is cut away and the knot reads as solid. The tube is a canal surface — the boundary of the union of spheres along the spine — which is what makes the occlusion exact: for an orthographic camera a point is hidden exactly when some sphere's near surface lies in front of it. Curve picks the spine: a p·q torus knot, the figure-eight knot, a Lissajous knot, or Tangle, a seeded sum of harmonics that is always smooth and always closed, so the Seed shuffles through endless genuine knots. Surface Cross winds a right- and a left-handed helix over each other — that is where the diamond moiré comes from — with Right and Left helix, Rings, Cross + rings and Longitudinals as the alternatives. Density comes from Strands, the number of parallel starts, more than from Turns. The radius is a function of arc length, clamped locally under the curvature radius: past it the tube's own wall folds inside its body and the drawing dissolves, so a tight bend quietly pinches instead. Strands passing within a tube diameter of each other are left to fuse, which the union of spheres renders correctly. Size is a true millimetre measurement, shrunk only if it would run off the sheet. Tip: wire Frame into Yaw for a spinning knot.", tags: ["3d","geometric","spiral","weave"] },
  "kolam": { t: "sikku (kambi) kolam: one or more closed loops winding at 45° through a grid of dots, built as Gerdes mirror curves. At every midpoint between two neighbouring dots the line either crosses straight into the next cell or turns and keeps circling the same dot; on the outer edge of the dot set it always turns, which gives the teardrop loops around the border dots. Every ray closes on itself, so the output is a set of closed strands. Layout Interlaced is the classic idukku-pulli chart (Rows display rows alternating Cols and Cols−1 dots — 4 × 7 is the 1-3-5-7-5-3-1 diamond), Square is Cols × Rows, Diamond is |i|+|j| ≤ Radius, Wired region puts dots wherever the wired closed shape covers the lattice at Pitch (any silhouette becomes a kolam); Rotate 45° turns the lattice. Turns % is the seeded density of interior turns. Strands Free keeps whatever the mirrors give (a plain n × m grid gives gcd(n, m) loops), Single line merges everything into one unbroken kolam by toggling turns where two strands meet, Target count aims at N. Loop reach stretches the border loops outward, Turn size the interior loops, Roundness rounds the 45° polygon into arcs (0 = angular chart). Crossings Cross draws real X crossings; Under gaps cuts the under strand at every crossing with a consistent alternating over/under — the knot look — at Gap mm. Render Centerline plots the line; Ribbon plots one distance-field isoline at Width/2 around the whole line, so crossings fuse into a single shape like rice paste on the floor; Contours nests Contours isolines Contour step apart; Centerline + ribbon draws both, the ribbon on Ribbon pen (Field cell is the SDF resolution). Dots draws the dot grid, Row numbers or Strand numbers write SFONT digits at the dots (Number size), rows counted from the bottom as kolam charts do. Pen per strand cycles a pen per closed loop. Pitch stays exact unless the drawing — loops included — cannot fit inside Margin, when it shrinks. Region input is optional (Wired region only); Style input is the second pin.", tags: ["geometric","grid","weave","decoration","symmetry"] },
  "lace": { t: "classic lace in three patterns: Doily (center flower, ring bands with seed-picked motifs — plain/double rings, zigzag diamond mesh, sector fans, picot loops — and a scalloped picot edge), Edging (header lines, mesh strip, scallops with fans and picots), Mesh ground (torchon diamond net with hashed spiders). Sectors, rings, detail, picots on/off, edging depth.", tags: ["mesh","organic","plants","round","weave"] },
  "lathe": { t: "revolved profile rendered as stacked ellipses (\"Rings\"), a mirrored silhouette (\"Profile\"), or both. Shed shapes: Skirt (the ceramic high-voltage insulator default), round wave, sharp zigzag; view tilt; ends taper automatically.", tags: ["round","structural","symmetry","wave"] },
  "lens": { t: "bulge/pinch distortion inside a circle (guide overlay).", tags: ["deform","round","warp"] },
  "lettering": { t: "heavy plotter capitals with a 3D side. Font Bold sweeps the built-in geometric capitals with a round pen, Block with a square pen, Roman with a broad nib at Nib angle so thickness follows stroke direction as in calligraphy (a vertical stroke at nib 0 is full Weight, a horizontal one a hairline). Every stroke is stamped into a distance field and the union is traced as one clean outline, so joints never double up; Fill shades the face from the same field as Outline, Hatch (angle and spacing) or Inline (concentric outlines stepping inward). Depth extrudes the letters toward Depth angle like sign-painter's block letters: the extruded body is the field's sliding minimum along the depth vector, the back silhouette is drawn only where it is not the face outline, and the visible sides are the outline stretches whose outward normal points along the depth. Side texture draws them as Zigzag (a sawtooth stripe at Side pitch), Lines (rules from face to back), Hatch or a plain Outline; the whole block is one field, so rules stop where they would run into another letter. Rotate turns the block, Slant shears it, Weight follows the fitted size. Lines with |, Align, Tracking, Line height, Y offset; the block shrinks to the margins on both axes, stroke overhang included.", tags: ["text","3d","fill","structural"] },
  "lfo": { t: "a value oscillator for animation: Sine / Triangle / Saw / Square / Noise loop, an integer number of cycles per loop (so wired Frame t stays loop-seamless), phase, and min/max output range.", tags: ["animation","math","noise","wave"] },
  "lichen": { t: "map-lichen and crustose growth after the real thing: Map builds polygon patches split by continuous wandering cracks, each patch grain clipped to its own cell; Rosettes grows ringed thalli with dark textured centers and pale rims (target-lichen); Colony scatters mixed-age patches across bare rock. Pens splits species across the palette; Crack width tunes the gaps (0 = seamless); fill style (mosaic / rings / stipple) is seed-mixed; sizes follow a natural small-to-large distribution.", tags: ["clip","dots","pens","round","scatter","texture"] },
  "linezones": { t: "op-art line compositions in the Vera Molnár tradition: a seeded BSP splits the canvas into rectangular zones (always the largest, along its long axis), each filled with a strict vertical or horizontal grating at shared pitch. A share of zones go Solid (0.45 mm pen-width black) or Dither (checkerboard dashes with seeded dropouts — the noisy data-column look); Diagonal cuts truncate a corner at 45° so the line ends form the classic staircase; Frame draws a solid border band, Zone gap a white gutter, Phase jitter de-syncs neighbouring gratings. Every line is strictly axis-aligned.", tags: ["clip","geometric","halftone","plants","region","retro"] },
  "lissajous": { t: "x/y sinusoids with frequency ratio and phase; the damping parameter turns it into a harmonograph decay spiral.", tags: ["geometric","spiral","wave"] },
  "loom": { t: "a dense woven mesh: warp (row) and weft (column) threads on a regular grid; Density is the thread spacing in mm, auto-coarsened to the point budget. Drape bends the fabric with low-frequency noise, Shape noise adds finer rumple at its own scale, and Drift drags the whole cloth toward an angle with a ramp across the sheet — all three are shared displacement fields, so the two thread directions stay woven together. The intact companion of the Torn modifier.", tags: ["grid","mesh","retro","structural","warp","weave"] },
  "lsystem": { t: "turtle-graphics rewriting systems. Presets (plant, Koch, dragon, Sierpinski, Lightning with midpoint displacement) plus editable rules, angle jitter and stochastic rule choice.", tags: ["fractal","machine","plants","warp"] },
  "magnet": { t: "attracts/repels points within a radius (guide overlay).", tags: ["deform"] },
  "map_import": { t: "plots a real city from an OpenStreetMap GeoJSON extract (overpass-turbo.eu → Export → GeoJSON). Roads weight by OSM class (motorway 3 strokes, primary/secondary 2, residential 1), Minor paths gates footways, Water draws rivers and lake outlines, Buildings their footprints — each family on its own pen. Fit Contain/Cover (Cover crops exactly at the frame), Rotate, and Simplify decimates dense OSM vertices in mm. Full guide: docs/MUUSIA-MAP.md.", tags: ["clip","map","structural","water"] },
  "mask": { t: "(deprecated — hidden from the palette since 2.40; old patches keep working) — clips paths by closed mask shapes (keep inside/outside). Use Container, which does the same for wired shapes and adds parametric regions, rotation, ±Gap and bisection-accurate cuts.", tags: ["clip","combine","region","round"] },
  "matem": { t: "A op B: + − × ÷ min max pow mod; inputs override the sliders.", tags: ["math"] },
  "mathknot": { t: "a torus knot p·q drawn flat with real over/under crossings: at every planar self-intersection the strand passing underneath is cut with a gap, so the knot reads as woven. Coprime p/q give true knots; Tube sets the torus thickness.", tags: ["3d","geometric","weave"] },
  "merge": { t: "combines up to several path inputs; later inputs plot later.", tags: ["combine"] },
  "mesh": { t: "jittered structural grid with selectable diagonals (none, \\\\, /, alternating, random) — truss look (compare Fabric/Net for cloth).", tags: ["geometric","grid","mesh"] },
  "meshslice": { t: "imports an STL and cuts it into flat sheet contours for building a layered object (lamp, sculpture) out of cardboard or plexi. Takes geometry from either source: a mesh wired into the Mesh input (Blob Mesh, or any future mesh generator) wins, and unplugging it falls back to the loaded file. Binary and ASCII STL, up to 120k triangles (decimate larger meshes first); the model is centred, scaled so its longest dimension is Size, rotated by Rot X/Y/Z, then sliced by horizontal planes at each sheet's mid-height — Slice by Count or by real Sheet thickness. Up to three negative primitives (Sphere, Cube, Dodecahedron; position and size in % of Size) carve the interior: the holes are cut per-plane in 2D rather than by 3D CSG, so the outer contour is clipped outside them and the hole contours are clipped inside the slice, and where a primitive breaks the surface the shell opens into a window. Rod holes adds 1-4 threaded-rod clearance holes (ISO medium fit M3-M10, or Custom) on every sheet, evenly spaced on a ring or placed by hand — a hole disappears on sheets with no material under it. The workflow runs preview first, cut second. CUT outputs are always true scale and never fitted to the canvas: Single slice, Frames (ANIMATE) (one slice per frame), Grid layout (the run tiled from the bed corner, columns fitted between the Bed margins, overflowing downwards when it is long) and Grid pages (ANIMATE) (the same tiling split into canvas-sized pages, one page per frame, each labelled P n/total — set the frame count to the page count and export SVG xN / DXF xN for the whole job as one zip). PREVIEW outputs are scaled to fit and stamped PREVIEW NOT TO SCALE: Contact sheet shows every sheet shrunk onto one canvas, which is how the negative primitives get placed without touching Size, and Isometric stack projects the real sliced geometry as a 3D stack (View angle, View elevation, Layer spacing x for an exploded view). Preview every Nth sheet thins dense runs, and preview sampling coarsens automatically so no sheet is ever dropped from the overview. All contours overlays every contour in place, a topographic drawing — and the honest way to find the core where every sheet has material before choosing a rod ring radius. The mesh travels inside the patch, so decimate before loading.", tags: ["3d","grid","mesh","stack","structural"] },
  "metaballs": { t: "a blob field (sum of r²/d²) contoured with marching squares into 1-5 nested iso-bands; segments are stitched into closed organic loops that merge where blobs meet.", tags: ["organic","terrain"] },
  "mini_squares": { t: "a field of axis-aligned squares packed on a hidden grid: larger multi-cell squares (Max square) are placed first, then single cells fill in around them against an occupancy grid, so neighbours share edges like a mosaic. Density is patchy fBm noise multiplied by a Spread falloff (Full / Corner / Center / Linear, strength via Fade) so the field crumbles away at its edge. Nest depth tucks smaller squares inside squares — concentric insets or corner-anchored knots (Mixed picks per square; each square keeps its own rng stream keyed to its cell, so its interior is stable while other params move). Gap shrinks every top-level square so shared edges separate. Structural invariant (validated): any two squares are interior-disjoint or strictly nested. Chain into Container or Wind Tunnel as an obstacle field, or drive Density with a value wire for animated growth.", tags: ["animation","flow","geometric","grid","noise","round"] },
  "minicanvas": { t: "lays out miniatures of full-canvas compositions on one sheet. Auto grid packs each wired input (A–F) into its own cell — a contact sheet. Fixed size makes production runs: set one mini size (postcard 148x105) and a count, and copies fill the sheet cycling through the wired inputs. L cut marks at every mini's corners and T fold marks (position in mm from the card's left/top edge, vertical/horizontal/both) go on their own Mark pen — plot in pencil, erase after cutting.", tags: ["clip","combine","grid","repeat","warp"] },
  "mirror8": { t: "reflection orbits around a movable centre: left-right, up-down, quad (4), or full 8-way D4 (cardinal + diagonal). Axes shown as guides. Mirrored copies honestly reverse stroke direction.", tags: ["repeat","round","symmetry","transform"] },
  "mm_paper": { t: "technical millimeter / graph paper: a grid of Fine-step lines with every Nth line promoted to Medium and every Nth to Major, each level on its own pen — the classic three-weight look from three colors, or plot the same pen 2–3 times for real line weight. Whole major cells snaps the grid down to complete major squares centered inside the margin; Border toggles the frame. Each line draws once at its highest level and lines serpentine for faster plotting; set a level's every to 0 to disable it, untick Fine lines for a cm-only grid. Wire a Stroke style for dashed engineering grids, or feed the output through Wave/Lens for distorted graph-paper art.", tags: ["geometric","grid","warp","wave"] },
  "moire_disc": { t: "one disc filled with fine regular structure, built to be overlapped: Rings, Spiral (one continuous line), Spokes, Hatch, Mesh, Hex / Grid / Random packed circles (optionally concentric via Circle rings) or Phyllotaxis. Pitch is the spacing, Angle rotates the pattern, Disorder morphs order toward chaos — and content never leaks outside the disc, so overlaps stay clean. Drop two with Pitch off by 5%, Angle off by 2-5 degrees or centers a few mm apart and the interference becomes moire; every knob has a value port, so Frame-driven moire breathes through an animation. Sector deg cuts the disc down to a pie slice — every content mode clips to the wedge with clean cut edges, Sector start turns the slice and the rim becomes the closed wedge outline (arc + both cut radii); wire the Frame clock into Sector deg and the disc fills up like a pie chart, or butt two complementary sectors with different contents into one two-fill pie.", tags: ["chaos","chart","geometric","hatch","retro","spiral"] },
  "mooncraters": { t: "cratered lunar terrain from a heightfield of bowl-and-rim craters. Top view (default) draws rim/floor outlines or a relief-displaced mesh; 3D view looks across the plain to a horizon — rotate with Yaw, raise the camera with Pitch. 3D Mesh uses classic silhouette occlusion; 3D Outlines drapes the crater rings over the terrain.", tags: ["3d","mesh","nature","round","terrain","warp"] },
  "morphlayers": { t: "in-between generator for layered plexi/glass stacks: wire the first and last compositions in and the node builds the missing layers by shape interpolation (Layers 2–12). Match picks the correspondence: Split & merge (default) is built for cut/fragmented geometry — the side with more paths assigns its fragments to the nearest target shapes, and each target's perimeter is partitioned into consecutive arcs proportional to the fragments' lengths, ordered by position along the outline, so glitch cuts morph smoothly into (and out of) whole shapes while keeping the cut structure; Nearest pairs by centroid and lets unpaired paths be born from / die into their own centroid (separate-blob scenes); By order cycles by index. Pairs resample to a common point count and closed 1:1 pairs align by start-index rotation + direction so the lerp does not twist. Output Sheets is frame-domain like the Sheets node (layer i on frame i, source pens kept, Stack View auto-detects the Layers count); Output Pens draws every layer at once with pen (First pen + i) mod 12. Ease Smooth slows both ends.", tags: ["animation","combine","deform","stack"] },
  "mosaic": { t: "mosaic tiling of the sheet with an optional figure. Wire closed shapes into Shape and they are laid in opus vermiculatum (Figure style Contour rows: tile rows following the outline inward, cut at Tile × Aspect and staggered; rows from the outer edge and from holes collide in the middle into the irregular core tiles of a real mosaic), as a clipped Grid, as a Fan of polar rings and sectors about the figure centre, or left blank (None: one outlined tile). The ground is opus regulatum, a square grid snapped so whole rows fill the margin box (Grid fit), clipped to a grout gap around the figure and continuing inside holes; the outermost Border rows take Outer row pen and Inner row pen. With nothing wired the sheet still fills with grid and border. Everything comes from one tile-id field: a fine raster (Field cell, 0 = Tile/8) gets a tile id per cell — nearest- outline distance and arc-length for the figure, grid cell for the ground — and tiles are the id boundaries. Render Tiles draws every tile as a closed outline shrunk by Grout/2 so the grout shows on paper; Seams draws every boundary once (lightest plot); Both draws both. Smooth rounds the raster boundaries (Chaikin passes), Min tile drops slivers, Irregularity jitters cuts, row edges and grid lines with the Seed for a hand-cut look. Pens: Figure, Ground, Outer row, Inner row. Ground None leaves only the figure.", tags: ["fill","grid","texture","decoration","hatch"] },
  "mountains": { t: "fBm heightfield rendered as ridge lines with true hidden-line removal (screen-space horizon buffer). Perspective (rows converge and compress with depth), oblique skew, island edge-fade, optional cross-line mesh.", tags: ["3d","mesh","nature","terrain"] },
  "move_scale": { t: "translate + scale (X/Y separable) around content centre, canvas centre, or a custom point.", tags: ["transform"] },
  "murmuration": { t: "a closed-form starling flock: every bird is a deterministic function of (time, index) — flock center follows a guide path, the flock breathes (pulse), swirls and stretches along travel. All time terms are sampled on a circle, so t=0 ≡ t=1: wire Frame's t into Time for a seamless loop. Flock paths: Wander / Oval / Figure-8 / Lissajous 2:3 / Trefoil, with a wander-mix for organic drift. Bird shapes Dash/Chevron/Dot with size variation for depth; optional flight-history trails whose point order equals flight direction.", tags: ["creature","nature","round"] },
  "mushroom": { t: "seven Finnish forest species as true 3D revolution models drawn from any camera angle: Yaw spins, Pitch tilts from side profile (0) to straight overhead (90). Chanterelle and Funnel chanterelle are wavy funnels with forking decurrent false gills that run down the stem; Black trumpet a deep ragged horn with sparse wrinkles; Gomphidius a slick cone cap with thick sparse gills; Bolete a barrel stem with net reticulation and a contour-arc bun cap (no gills); Fly agaric the classic dome with white warts, ring and bulbous base; Sheep polypore a lumpy bracket with wobbly contours — Mix rolls a species per copy. Gills are traced on the actual 3D surface with arc-length forking (Gill spacing) and visibility comes from one surface-normal test, so funnels show their inner wall and full rim when you look in and capped species hide their gills from above. Chaos is the organic-disorder master: multi-octave lobed rims, folds that twist with height, trunk sway, wandering gills with seeded breaks and loose interstitial dashes. Count scatters seeded copies with spin, lean and size jitter — instant shirt-print sheets — and Cap texture Stipple dusts the cap top with dots for the classic top-view print. The Mesh output carries the FIRST mushroom as a watertight normalized mesh for Mesh Slice.", tags: ["3d","mesh","nature","organic","plants"] },
  "myceliumfill": { t: "grows organic flesh along a line network: parallel strands follow each input line and the width swells near junctions (3+ path ends meeting, or crossings between paths), so joints read thicker — a slime-mould look on a Voronoi or Network input. Strands invading a neighbouring strut's territory are cut, except near junctions where they merge; Waviness adds hyphal wobble, Taper thins open ends.", tags: ["connect","fill","mesh"] },
  "myco_net": { t: "hyphal growth: queued tips step through noise-steered incremental turns and split into binary branches at a seeded rate; edge and point budgets end strands. Spore count, growth cycles, split rate, wander, internode, spawn radius.", tags: ["connect","noise","organic","plants"] },
  "nanotubes": { t: "3D carbon wireframes: Fullerene C60 (exact truncated- icosahedron coordinates — 60 atoms, 90 bonds, 3-regular), armchair (n,n) and zigzag (n,0) nanotubes built by rolling a real honeycomb lattice into a cylinder (n sets the diameter), Graphene sheet, Nanotorus (the lattice closed seamlessly in both directions) and Onion (nested C60 shells). Yaw / Pitch / Perspective are value-drivable — wire Frame into Yaw for a spinning molecule; Front half culls bonds facing away by surface normal for a solid look; Atom dots marks the carbons.", tags: ["3d","connect","dots","grid","mesh","scientific"] },
  "needlepunch": { t: "(penout) — converts lines into needle piercings for a needle mounted in the pen carriage (paper raised on foam): each punch is a zero-length path whose points carry z = Depth mm below the machine profile's pen-down contact, read by the G-code export. Punch at Interval walks each path every Interval mm (with Offset and Punch ends), Intersections punches every line crossing including self-crossings, Both combines them, Centers punches once at each path's centroid — chain Braille or Single Marker into it. Spacing mod varies the interval along the arc (Wave / Noise / Ramp / Jitter, up to ±100 % swing, floored at 0.1 mm); Min gap merges punches so the needle never stabs the same hole twice. Punches preview as round dots. Bed-Z machines only (servo mode ignores z), and keep it LAST in the chain — any modifier after it strips the z component.", tags: ["dots","noise","penout","round","text","wave"] },
  "negspace": { t: "clips Fill into the space a Shape does NOT use: the shape's lines plus a clearance band, and the inside of its closed paths, count as occupied, and the fill flows around them — a background behind Tubes without touching it. Inverse mode keeps the fill only INSIDE the used space. Works with any geometry, open or closed, unlike Mask.", tags: ["clip","combine"] },
  "nested_circles": { t: "overlapping ring- or ray-filled discs woven into an over/under illusion. Order: Weave interlocks two discs along their center line (the classic yin-yang poster) and cycles three-plus into a pinwheel; Weave fill uses angular sectors so the central multi-overlap stays filled; Stack is painter order. Background Opaque gives every disc a solid backing (hides what lies beneath even between its own rings); Transparent overprints complete discs like stacked pen layers. Gap cuts a white halo around the covering disc. Discs alternate Pen A/B.", tags: ["clip","geometric","pens","plants","round","weave"] },
  "net": { t: "netting with selectable mesh: Diamond (fishing net), Square, Triangle, Hexagon (chicken wire, drawn without doubled edges). Whole net sags like it hangs; irregularity jitters the knots; strands are subdivided so they bend smoothly.", tags: ["mesh","structural","warp"] },
  "network": { t: "a seeded graph laid out by deterministic force simulation: nearest-neighbour links plus a few long-range ones untangle into constellation diagrams. Edges stop at node circles; node size can follow connection count; wire Iterations to animate the untangling.", tags: ["animation","chart","connect","physics","round","structural"] },
  "numerals": { t: "numbers in sixteen numeral systems from around the world as plottable strokes. Digit scripts (Western, Eastern Arabic, Persian, Devanagari, Mongolian, Chinese) render digit by digit; value systems convert the whole number: Roman (subtractive, N for zero), Maya (base-20 dot-and-bar stacks, shell zero), Cistercian (one monk-glyph per number 0–9999), Babylonian (base-60 cuneiform wedges), Counting rods (alternating orientation per place), Kaktovik (Iñupiaq base-20 connected strokes), plus Braille, Dot matrix 5×7, 7-segment and 14-segment displays. Value takes several numbers separated by spaces and Tokens per line wraps them into a table — run a counting table per system, or stack the same number in every system down the sheet.", tags: ["connect","dots","repeat","text"] },
  "occlude": { t: "(occlusion) — hidden-line removal. Wire closed shapes into the Occluders input to hide the Lines input behind them, or leave it unwired for painter mode where later closed shapes in the set hide earlier paths. Gap grows (+) or shrinks (-) the occlusion region so lines die cleanly before an edge.", tags: ["3d","region"] },
  "offset": { t: "parallel copies at a distance, with Clean corners cusp removal.", tags: ["pathops","repeat"] },
  "op_tunnel": { t: "op-art perspective tunnel: an (optionally irregular) polygon is split into wedge sectors from a vanishing point and each sector is striped parallel to its outer edge with geometrically shrinking spacing — Edge gap sets the stripe period at the rim and a per-sector ratio keeps rim density uniform even off-center. Depth % is the center hole, Fill step hatches every second band solid for the painted look, and Glitches punch seeded rectangular patches where stripes shift half a period inward, flipping the apparent color. VP X/Y place the vanishing point.", tags: ["3d","animation","chart","geometric","hatch","retro"] },
  "orbit_scribble": { t: "the looping-thread tangle: each strand is ONE continuous stroke that keeps drawing circles while its center wanders inside a rounded noise cloud and the loop radius breathes — scribbled orbits without lifting the pen. Built-in Beads stamp ink dots (tiny filled spirals) along the strands on their own pen, and Core falloff thins them toward the cloud edge so the fringe loops run bare.", tags: ["animation","dots","noise","organic","round","spiral"] },
  "organicrings": { t: "concentric organic rings from mixed strands — solid wavy lines, beaded dot rings, dashes, doubled lines — around a clean hollow center, like an agate slice or dot-art mandala. All rings deform in one shared noise field; Bundling clumps them into tight groups, Merges peels strands across to the next ring, Bulges plants knot-like eyes that part a band of rings in both directions (lens pockets), Halo scatters a clumpy dot mist dissolving outward. Pens used cycles ring colors — four metallics on black is the classic.", tags: ["dots","organic","plants","scatter","symmetry","weave"] },
  "origami": { t: "crease-pattern style folded-paper facets.", tags: ["structural"] },
  "origami_glitch_fold": { t: "mirrors everything on one side of an adjustable fold line back across it, with a distance-proportional crease warp; optional Keep Original for layered folds. The fold pivots around a movable point (Pivot X/Y or the canvas center) and Axis Position slides the line along its normal; dashed guides show the fold line, pivot and mirrored side. Output clamped to the sheet.", tags: ["deform","symmetry","warp"] },
  "outline": { t: "encloses each stroke in a closed capsule (offset both sides + semicircle caps); closed paths become two-ring bands. Turns strokes into fillable shapes: Outline → Hatch Fill = fat filled lines.", tags: ["decoration","hatch","round"] },
  "parallel_lines": { t: "a dense field of vertical lines rising from the bottom margin to a terraced height field, with expressive tops. Grass flops every tip in its own random curl; Shoulder combs the lines near each terrace edge over a shared pivot in concentric arcs and hangs them down the face; Cascade sweeps them over the edge into parallel diagonal falls that steepen back to vertical. Levels quantizes terrace heights (1 = one flat field), Plateau width and Relief shape the steps, Tail length scales curls/hangs/falls, Messiness and Wobble loosen it. Pen travel is uniformly bottom → top → over the tail (brush-friendly).", tags: ["geometric","noise","plants","round","texture"] },
  "patternfill": { t: "shades every closed shape with a drawn texture from a pattern library: Hatch, Cross-hatch, sketchy Scribble, Stipple, small Circles, Chevron rows, broken Dashes, Crosses, random Sprinkles — or Mix, giving each shape its own pattern like a swatch sheet. Offset from edge is distance-based (negative bleeds past the outline and into holes); nested shapes act as holes; Gradient fades ink toward the Light angle per shape; Vary per shape rotates and loosens the pattern; Wobble adds hand tremor; pens spread or inherit. Compare Hatch Fill: that is the fast plain hatcher, this is the texture library.", tags: ["dots","fill","hatch","region","scatter","texture"] },
  "pcbtracks": { t: "printed circuit board copper: octilinear tracks (45-degree bends only) routed between round pads, IC footprints as twin rows of pads feeding tracks outward, and via dots along the runs.", tags: ["dots","round","structural"] },
  "pebble": { t: "a rock two ways. Spiral shells fills a pebble outline with continuous spirals winding from the edge into 1–3 eye points — Edge packing crowds the shells at the boundary, Weave rotates each turn so they cross into a moiré net; Rot Y spins the drawing, Rot X tilts it flat. Mesh renders the same rock as a 3D wireframe (Surface: Solid or Transparent). Round–Angular morphs from smooth pebble to faceted chunk in both modes; Facets, Irregular and Detail shape it. Distinct from Stone (flat facet illustration).", tags: ["3d","flow","mesh","nature","spiral","weave"] },
  "pencycle": { t: "assigns pens to whole paths in rotation.", tags: ["penout","pens"] },
  "pendulum": { t: "chained damped oscillator arms (1–3). Each arm's pivot rides the previous tip; Coupling modulates an arm's frequency by the previous arm's angle (real interaction: 0 = pure epicycles, high = chaos); rotating table; exponential damping. One continuous stroke.", tags: ["chaos","machine","physics","wave"] },
  "perfmesh": { t: "a 3D wireframe solid (pole-free cube-sphere, cube or pyramid) as an organic quad mesh with hidden faces removed. Mesh flow warps the grid with noise so the quads swim; Mountains raises 4-octave terrain radially (continuous across edges); Holes punches funnel craters with raised rim lips, concentric collar rings and converging radials, the center opening cut through. Surface picks Solid (hide back) or Transparent. Adaptive refinement keeps funnel walls curved. Rot X/Y to spin — wire Frame for a rotating meteor.", tags: ["3d","chart","flow","geometric","mesh","terrain"] },
  "persp_hall": { t: "one-point perspective corridor built as a real 3D box: walls, floor and ceiling (plus optional Far wall, stepped Ledges and Doorways) are projected through a pinhole at the vanishing point (VP X/Y %) and every plane is filled with hatch at constant 3D spacing, so the lines rush toward the VP the way a ruled perspective does. Mode Grid rules every plane in both directions — the classic laser-line perspective grid; Hatch lets each plane choose Across (lines at constant depth: vertical on walls, horizontal on floor and ceiling), Along (lines converging to the VP), Both or None. Gap is the spacing in mm at the sheet edge; where the projected spacing falls under Min gap lines are dropped — every 2nd, 4th… in ruled work, at random with the same survival rate in hand-drawn work — so the hatch continues to the vanishing point without clogging, and the density bands where that happens sit at one shared depth on all four planes whatever the Aspect. Walls Aspect is a symmetric box seen from its axis; Sheet edges moves the eye off the corridor axis so the four corner lines run exactly into the frame corners and every wall stays on the sheet however far off-centre the VP is. Ledges adds blocks along both walls at a geometric Rhythm (Ledge height %, Ledge depth %, Ledge / bay, Stagger sides), with white Doorways of Door height % left between them; occlusion is exact — blocks hide the wall and floor behind them and nearer blocks hide farther ones, all done as t-interval arithmetic on the projected segments with 1/Z linear along a line. Hand 0 is ruler-straight 2-point segments; raising it adds low-frequency wobble, a slight bow, spacing drift, ragged over/undershooting ends, broken strokes and the occasional missed line. Edges draws the construction lines (corner lines, block edges, door frames, far wall) with Edge pen. Point budget 112k with early stop.", tags: ["3d","geometric","hatch","structural"] },
  "photo_trace": { t: "recovers a real object's outline at true physical size and position from a photo. Print `public/markers/muusia-markers-a4.png` (or `-a3`) at 100% scale — the bar on the sheet must measure exactly 100.0 mm — lay the object on the sheet, photograph it from as overhead as possible and load the photo. The four 15 mm corner markers (the hollow one is the orientation anchor, so any camera rotation works) fix a pixel→millimetre perspective homography; the largest dark shape inside them is contour-traced into one closed path. Threshold and Invert set the dark cutoff, Simplify (RDP) and Smooth (Chaikin) clean the contour, Grow offsets it outward in mm for glue clearance (negative shrinks), Rotate matches how the printed sheet lies on the plotter bed, and As photographed keeps the outline exactly where the object lay — plot around the blank spot, then glue the object back in. Chain into Wind Tunnel's Obstacle or Container. The sheet plane is perspective-corrected but object height adds a small safe-side parallax, so tall objects trace slightly large.", tags: ["image","region"] },
  "phyllo": { t: "sunflower-seed spiral (golden angle); dot size can grow with index.", tags: ["geometric","spiral"] },
  "pins": { t: "sewing pins: straight shafts with a ball head at the tip. Chaos runs from a neat grid where every pin points at Angle (0) to a fully scattered jumble of random positions and directions (1); the shaft stops exactly at the ball's edge, pen travelling tail → head. Head fill draws the ball as an outline, concentric rings or one continuous inward spiral; Head pens cycles the balls across several pens like a real pin assortment while shafts keep Shaft pen; Bend curves the needles. Every pin fits the margin whole. Unlike Comets, whose few tails share a sun direction, Pins is an order-to-chaos field of up to 200 needles.", tags: ["chaos","geometric","grid","pens","scatter","spiral"] },
  "plaid": { t: "overlapping hand-drawn grids as planes in a fully rotatable 3D world. Each grid gets a seeded character: cell size, band structure (every line is a bundle of 1..Bands parallel strokes, the tartan look), extent, wobble and dropout. Arrangement Stack floats parallel panes in depth like sheets of glass so orbiting slides them past each other in parallax, Box aligns planes to the three axis orientations, Random tumbles them freely; Depth spread scatters the panes. Yaw and Pitch orbit the camera by hand and Perspective bends the view from flat orthographic to a deep pinhole lens (a true perspective — straight lines stay straight). Phase adds a full 360-degree orbit turn from 0 to 1: wire ANIMATE Steps into it and the loop closes byte-perfectly, with Bob adding a pitch sway that also loops. Dropout and wobble are hashed per line, never from phase, so frames never flicker, and the scale is measured over the whole orbit so no frame ever leaves the sheet. Pen per grid cycles pens by plane.", tags: ["3d","animation","geometric","grid"] },
  "pleat": { t: "a ribbon of parallel lines folded like a strip of paper: the band runs along the sheet (Orientation Vertical / Horizontal, Length % of the margin box, Width) and kinks at every crease; between creases each of the Lines is straight, so the strip reads as a stack of tilted panels in perspective. Creases are written as a token script, one token per crease, characters combining inside a token: `-` straight, `/` `\\` tilted by Tilt, `^` `v` chevron (apex toward the start / end of the strip by Chevron mm), `<` `>` shifted sideways by Shift, `(` `)` narrow or wide by Pinch, `x` twist (the line order flips from that crease on — an hourglass; a second `x` flips back), `~` or `=` force a fully cylindrical or flat line distribution on that crease. Preset gives the classic folds — Zigzag is the drawn-paper look (chevron creases alternating left and right, wide fans at both ends), Accordion tilted creases, Twisted, Fan — and Custom reads the Folds field (unknown characters are ignored, an empty script is two straight creases, 60 tokens max). Shade pushes lines toward the panel edges like a rolled cylinder; Spacing variation jitters the crease intervals with the Seed. Construction lines extend every crease edge from the ribbon corner to the margin box on Guide pen, the way the pencil guides survive on the original drawing (corners already on the sheet edge get none). Each ribbon line is one continuous stroke end to end.", tags: ["geometric","repeat","structural"] },
  "pointcloud": { t: "3D point clouds projected to the sheet. Source: a file (.xyz/.csv/.txt with x y z per line, or ascii PLY) or a built-in parametric cloud (Torus, Sphere, Cube, Octahedron, Pyramid, Spring, Mobius, Trefoil, Klein bottle, Roman surface, Helicoid, Wave sheet, Galaxy). Keep size scales by the rotation-invariant 3D bounding sphere so the object stays the same size while Yaw/Pitch turn; off = always fit to sheet. Bitcrush: Crush % randomly drops points (seeded), Quantize % snaps to a 3D grid — both act before meshing. Output: dots, wire (3D k-nearest mesh) or both; Max edge % trims long jumps, Depth pens splits near-to-far across pens.", tags: ["3d","connect","dots","mesh","pens","text"] },
  "polkadots": { t: "plain dots or circles on a grid: Square rows, Hex (net-like offset rows), or Random with even spacing. Dot size 0 plots a bare pen touch; larger sizes draw circles; Size variation makes the field breathe.", tags: ["dots","geometric","grid","round"] },
  "polystudio": { t: "polyhedra rendered face by face in 3D. The catalogue is generated rather than tabulated: the five Platonic solids are exact and every Archimedean and Catalan form is derived from them by three operators the node implements — rectify (edge midpoints), truncate (corner cutting) and dual (polar reciprocal) — so Cuboctahedron is a rectified cube, Rhombicosidodecahedron a twice-rectified icosahedron and Rhombic triacontahedron the dual of the icosidodecahedron, all with planar faces. Prisms, antiprisms, pyramids and bipyramids take any side count; Geodesic sphere subdivides an icosahedron 1–4 times onto the sphere. Each face is filled IN ITS OWN PLANE before projection, so the pattern rides the perspective instead of lying flat on the paper: Concentric inset nests the face into itself (pair it with Face inset for the white channel along every edge), Face hatch, Spiral, Nested rings, Centroid fan and Dots. Back faces are culled by their true normal, kept (Transparent) or thinned (X-ray); Even density divides the fill spacing by each face's foreshortening so a face seen almost edge-on thins out instead of collapsing into a solid sliver. Stellate raises each face on a pyramid along its normal — negative dimples it inward — and reshapes the real solid, so it reaches the Mesh output; Explode slides faces apart as a drawing convention only. Three outputs: Faces, Silhouette (the projected outline as one closed path, for a heavier pen or a cut line) and Mesh — the rotated, normalised triangle payload, so Mesh Slice cuts exactly what the screen shows. Rotations and Stellate are value ports.", tags: ["3d","geometric","mesh","space","structural"] },
  "portrait": { t: "(gen / textimg) draws a photo the way a portraitist works. Load a photo (JPEG/PNG; EXIF-corrected, resized to 1280 px, frozen to the node) and press Analyze face to freeze a face analysis into the node - landmark chains, parsed hair/glasses/skin regions and a hair flow field, all carried inside the patch. Modes Features+tonal and Features only turn the analysis into drawing: chains become smoothed splines pruned in importance order by Line economy (max = every contour, min = just the eyes; the face oval splits into a high-importance jaw arc and an early-dropping upper arc), glasses come from the parsed region behind their own checkbox, and hair is drawn as FLOW - streamlines seeded in the hair mask along the frozen flow field, density from darkness. Beards are detected as texture at Analyze time (no parsing class exists for facial hair) and drawn as flow like hair with tighter lanes, and the jawline is clipped outside the beard mass - the node draws the beard, not the chin bone through it. Group photos work: every found face is drawn (analysis carries them all, largest primary) and the warning line reports the count. Feature lines take the node's Pen; tonal rounds continue on the following pens with the feature ink already deposited, so shading avoids the lines. Mode One line is the Picasso portrait: the pruned chains of every face are ordered by a small endpoint tour and linked with light arcs bulging over the cheeks and forehead - one unbroken line (requires an analysis, empty without one). Sketch nerve brings the Tresset look at any nerve > 0: contours re-stated by nervous drifting passes that fragment into partial arcs, flyaway line ends, and a structural shift in the shading - tonal ink is gated to a tight zone around the feature lines and piles onto them as short scribbles whose density follows local tone (dark knots, light single lines, white in between), while rare worm-strokes escape outward on meandering courses; 0 is the clean drawing, bit-identical to before. See MUUSIA-PORTRAIT-MANUAL.md for parameter meanings and presets. Tonal mode needs no analysis at all: residual rounds (draw only where the image is still darker than the ink placed so far) under a coarse-to-fine \"squint\" blur, Flow/Cross-hatch/Mix hatching, a Focus ellipse for manual attention, hard stops at the White cutoff so eye whites stay clean, and the locked prefix invariant that makes round = pen work - the G-code pauses at every round and you decide at the machine whether to continue. Spiral and TSP draw the whole image as one unbroken line. Without a valid analysis the feature modes degrade to pure Tonal. When selected, the overlay shows the analysis chains and regions as dashed guides before any ink.", tags: ["flow","halftone","image","portrait","texture"] },
  "potato": { t: "asymmetric blobs (low-frequency harmonics + random squash) with optional \"eyes\" texture as dots or curved arcs. Placement: No overlap keeps every potato fully separated using its true extent (fewer may fit on a tight sheet); Loose allows touching and light overlap.", tags: ["audio","dots","nature","texture"] },
  "powerpole": { t: "wireframe 3D utility poles: Finnish Wood (single pole, crossarm, pin insulators, guy wire), US Utility (double crossarm, cylinder transformer), Japanese Concrete (stacked arms, transformer drums). Wires hangs catenary cables from the insulators; rotate with Yaw/Pitch, wire Frame to orbit.", tags: ["3d","mesh","round","structural"] },
  "radat": { t: "concentric rings (athletics-track offsets) around a centre. Ring count, spacing, start radius.", tags: ["geometric","round"] },
  "radial_burst": { t: "lines fleeing a center point: squiggly hairs radiate outward and new hairs are born mid-flight wherever the neighbour gap exceeds Hair spacing, so the coat stays evenly dense from core to rim relative to the LOCAL blob edge at any Edge variation. Waveform: Zigzag, Sine, Square, Saw, Seismic (quiet stretches broken by bursts) or Straight; Inner radius opens a hole; the pivot is movable. Each hair is one stroke drawn inside out.", tags: ["animation","audio","organic","wave"] },
  "randlines": { t: "Molnár-style random segments: free endpoints or fixed length with angle constraints (any / H+V / diagonals / 45° quantized).", tags: ["scatter","scientific"] },
  "raydrape": { t: "Houdini-style projection: every point of A is cast along a direction until it hits B's lines, so A drapes over B like fabric or rain. Misses keep their place for a continuous drape; Offset lands the line just before the surface.", tags: ["combine","water"] },
  "rayfill": { t: "fills every closed shape with straight rays that fan out from a centre and are clipped to the shape by even-odd rules, so nested shapes act as holes. Centres Per shape gives each shape its own centre by Placement: Centroid (starburst), Random inside (off-centre burst), Edge (a fan from the outline) or Outside (sweeping near-parallel chords through the shape) — Mix lets each shape draw its own kind for the varied look of a hand-filled map. Shared scatters Centres count seeded centres over the margin box (best-candidate spread); Nearest centre fills each shape only from the centre closest to it, All centres lets every centre radiate through the whole sheet so one burst spills across many shapes. Spacing at rim sets the ray gap at the far edge — rays converge toward the core exactly like a real pen starburst; Core gap opens a hole there instead of an ink pool. Fill fraction fills only a seeded share of the shapes. Jitter wobbles ray angles, Min length drops slivers, Alternate direction plots rays as a zigzag (off = every ray drawn from the core outward). Keep outlines passes the shapes through, Inherit shape pens colours the rays with each shape's pen.", tags: ["fill","geometric","hatch","region"] },
  "rectcollage": { t: "cuts random rectangles of different sizes out of the input and rearranges the pieces at random positions, optionally rotated in 90-degree steps. Unlike Tile Shuffle's regular grid, pieces vary in size and land anywhere; Keep rest passes the uncut remainder through underneath.", tags: ["clip","grid"] },
  "regmarks": { t: "registration marks in selectable corners (+ optional centre): cross, printer's circle-and-cross, or inward corner-L; adjustable insets. For multi-pen registration and scan alignment.", tags: ["round","structural"] },
  "reititys": { t: "legacy in-graph route optimizer (hidden from the palette; routing now lives in the export panel as Optimize route + Preserve direction).", tags: ["penout"] },
  "retromesh": { t: "80s diagram wireframes in true perspective. Hourglass is the wormhole double funnel (rings + meridian spokes from a shared throat; Flare, Throat, Height shape the profile), Funnel and Horn its single-ended siblings, Laser floor the synthwave grid receding to a vanishing point with noise Terrain that leaves a flat center corridor and an optional Horizon line. Perspective runs from near-orthographic to wide-angle; drawn transparent (no hidden-line removal) like the retro prints. Pair with Solids for a planet disc.", tags: ["chart","geometric","mesh","plants","retro","terrain"] },
  "reverse": { t: "flips path direction: all, every 2nd (manual boustrophedon), or random. Because direction is data.", tags: ["pathops","penout"] },
  "ribbon": { t: "a wandering backbone with parallel companion lines (1–60). Shape Line runs the spine left to right across the sheet; Ring closes it into a seamless loop around the canvas center (Ring radius sets the base size, Wander makes the loop breathe; the noise is sampled periodically so there is no seam) with every filament a closed stroke. At lines = 1 it is a clean single guide curve — a good Spine for Ruler or Follow Lines.", tags: ["geometric","noise","round"] },
  "ripple": { t: "water reflection with surface disturbance. Everything above the Waterline is mirrored below and disturbed by horizontal ripple bands whose displacement grows with depth — reed stalks wiggle, a boulder's underside gets the jagged rim. Breakup fragments the reflection into dashes with depth, Stretch scales it, Pen shift moves reflections to another pen (originals pass through untouched). Area confines the effect to an adjustable Pool (half-ellipse pond, wobbly rim) or crisp Box under the waterline; region and waterline show as guide overlays. Pairs with Water for the surface itself.", tags: ["deform","region","symmetry","warp","water","wave"] },
  "ripple_chain": { t: "chains of concentric ring clusters strung along the input path like beads. The walk stamps a cluster every 2 x radius x Spacing (1 = touching); size breathes via a slow Wave along the path, long-tail per-cluster Variation, and — when a curve is wired into the Amplitude input — an envelope sampled from that curve's deviation, so Sound Line's waveform drives ring sizes along the path. Ring gap, Hollow core, per-ring Drift, Scatter off the path and Satellite companion rings shape the look. The point budget is shared between input paths by arc length and an oversubscribed path thins evenly along its whole length — large radii never leave loops or tails blank.", tags: ["audio","decoration","plants","scatter","spiral","wave"] },
  "river": { t: "meander-migration solver: the river centerline's per-point curvature is measured with an upstream flow-memory lag and every point migrates toward the outer bank a little each step — bends grow, wander downstream, and when a loop folds back on itself the neck is cut and the abandoned arc is left behind as a closed oxbow lake. All simulated steps stack into one drawing: Steps sets the simulation length, Draw every picks the inked intermediate channels, the final channel and the oxbows draw with their own pens. Migration is the erosion speed, Flow memory shifts meanders downstream, Channel width is the neck-cutoff distance, Confinement pulls the river back toward the valley axis. Wire Steps or Migration from the Frame clock to animate the river carving itself.", tags: ["animation","chart","flow","nature","physics","water"] },
  "roadmap": { t: "procedural city map. Seeded Voronoi districts each get a street pattern — grid, organic, radial rings-and-spokes, sparse blocks — built by recursive block subdivision, so streets meet in T-junctions, kink at discrete points and trail off into dead ends (Irregularity drives all of it; Raggedness breaks strokes into the worn dashed look). Three road weights: single-stroke streets, double-stroke arterials between district centers, triple-stroke motorways in long straights with wide rounded bends (Motorway bend 0 = dead straight) plus slip-road Ramps at crossings. River and lakes carve water with shorelines — streets keep off the banks, motorways bridge over. Fields hatches farm patches into empty districts, Landmarks stamps filled squares. Pens: roads, water, fields.", tags: ["fractal","hatch","map","structural","water"] },
  "rootveg": { t: "the Kosmos Botanika root cellar, Potato's companion: Kind Carrot, Turnip, Swede, Sugar beet, Onion, Garlic, Leek, Cauliflower, Cabbage, or Mix (a seeded shuffle that shows every kind before any repeats). Each specimen is a botanical-plate outline built from a kind-specific half-width profile along a vertical axis — carrot cone with a rounded shoulder, flat turnip, necked swede, wedge beet, onion and garlic with a cut neck, leek shaft, curd dome, leaf ball — roughened by Irregularity with different harmonics on each side. Texture adds the lines that belong to the kind: carrot ring scars, onion skin meridians, garlic clove ridges and papery cracks, the beet's two grooves and wrinkles, leek shaft lines, cauliflower curds, cabbage leaf edges and veins, and the purple shoulder of turnip and swede on Accent pen. Tops Leaves draws feathery carrot tops, spoon leaves on stems for turnip / swede / beet, hollow onion tubes, flat garlic and leek blades, wrapping cauliflower and cabbage leaves (each blade with a midrib), Cut stubs the trimmed stems; Top length scales them (never more than that above the body). Roots hangs fine wandering root hairs from the right places — an onion / garlic / leek tuft at the base, a carrot taproot tail with lateral hairs, beet rootlets along the lower body, a turnip taproot — every hair starting on the outline and never re-entering the body; Root length scales them; cabbage and cauliflower are cut and have none. Size is the body height exactly, Size variation scatters it downward; Rotation Upright / Tilt (± Tilt °) / Random; Placement No overlap keeps whole specimens (tops and roots included) apart by bounding box — a rejection sampler like Potato's, so oversized requests fit fewer — Loose lets bodies touch. Pens: body, Accent, Tops, Roots.", tags: ["nature","organic","plants","scatter"] },
  "roundcanvas": { t: "crops everything to a round canvas whose rim can be distorted: Distort pushes seeded noise into the outline, Lobes sets the bulge count — clean circle to wobbly blob. Content is clipped at the rim (Edge gap keeps a quiet margin), Invert keeps the outside, Draw edge plots the rim on its own pen, offsets move the canvas. Same seed in two instances = registration across layers.", tags: ["clip","noise","round","warp"] },
  "ruler": { t: "tick scales with a minor/medium/major hierarchy. Linear or logarithmic (slide-rule) spacing; numbers (built-in single-stroke font) or cycling symbols at majors; ticks up/down/both. Optional Spine input: the ruler follows any path — feed a Ribbon or Tracks ring to get curved measuring tape.", tags: ["chart","round","scientific","text"] },
  "runes": { t: "asemic writing: a seeded alphabet of invented angular glyphs laid out in words and lines. Repeating letters from a finite alphabet make it read as language; every seed is a new script.", tags: ["text"] },
  "sand_line_hatch": { t: "broken multi-segment scanlines whose ink probability is noise × density, producing grain-gradient fields; runs collapse to 2-point segments and lines alternate direction (serpentine).", tags: ["geometric","hatch","noise","texture"] },
  "sand_painting": { t: "a raked dry garden. Open rake draws calm parallel furrows; Flow around stones bends them around seeded rocks; Island rings lays nested contours around each stone; Spiral rake is one continuous basin; Mixed garden combines flowing furrows with cleared ring islands. The sand is cleared wherever a stone stands, so the rake never crosses a rock. Rake spacing is the physical distance between grooves and Detail the curve sampling — extreme settings coarsen themselves to hold the point budget. Stone size variation and irregularity turn the ellipses into real lumps; sand and stones take separate pens.", tags: ["flow","nature","organic","texture"] },
  "satunnainen": { t: "a seeded random number in a range; re-rolls per seed, not per frame.", tags: ["math"] },
  "scan": { t: "seismograph / EEG channel rows: a calm baseline per channel with 1–3 seeded burst events per row. Detail sets the channel count; annotations (ticks) go on their own pen.", tags: ["chart","scientific"] },
  "scatter": { t: "breaks paths into displaced fragments.", tags: ["clip","scatter","warp"] },
  "scribbletype": { t: "the medical alphabet as real pen strokes: the pen traces each character's skeleton as one continuous stroke while a Scribble mode displaces it — None (clean trace + hand tremor), Coil (small dense loops advancing ALONG the strokes like a coiled spring, form readable at any messiness), Sine (perpendicular wave, Loops = cycles), Seismic (calm baseline + seeded quake bursts), or Glitch orbit (character-sized loops that swallow the form). The Alphabet select swaps the skeleton: Latin, Runes (the real 24-rune Elder Futhark with standard Latin transliteration), Hieroglyphs (invented Egyptian-flavored pictograms), Cuneiform (cuneiform-STYLE invented wedge signs — real cuneiform is syllabic, no faithful letter map exists), Alchemy symbols, or Asemic — the Seed generates a whole coherent invented script where the same letter always maps to the same glyph. Tracking goes negative for piled scrawl.", tags: ["round","spiral","text","warp","wave"] },
  "sdfcontours": { t: "(deform) — distance-field isolines around ALL input geometry: unlike per-path Offset, nearby shapes merge into one smooth halo, like metaballs. Inside adds negative offsets within closed shapes; open lines get stadium-shaped halos.", tags: ["deform","region","terrain"] },
  "seams": { t: "moves the start point of every closed path so pen-down seams stop lining up: concentric Rings fills otherwise plot a visible seam column where every circle starts and ends. Golden spiral steps each seam by the golden angle so no two ever align (the right choice for nested rings and needs no seed), Random scatters them with the Seed, Fixed step rotates each successive path by Step degrees. The cut lands at an exact arc-length position — a new point is interpolated, z plunge values included — so the geometry is untouched, only the draw order around the loop changes. Overlap makes each path run past its seam by that many millimetres and emits it as an open path, hiding the pen dot under fresh ink (0 keeps paths closed; try 0.8–1.5 mm for gel pens on dark paper). Open paths pass through untouched.", tags: ["pathops"] },
  "setpen": { t: "recolors the input onto another pen. All moves everything to the target pen; Single remaps only one source pen and leaves the rest untouched — handy for swapping a single color in a multi-pen patch.", tags: ["penout","pens","plants"] },
  "shade": { t: "charcoal-style tonal shading for closed shapes driven by a MOVABLE light (value-drivable X/Y % with an overlay guide): a darkness field is built inside each shape — edge band × light facing + corner kernels (Concave bias pools ink into notches) + ambient + body gradient — and rendered as stacked rotated hatch levels, so tone builds like layered pencil. Directionality 0 is pure ambient occlusion; shapes nested inside another act as holes; open paths pass through untouched.", tags: ["fill","halftone","hatch","region","round"] },
  "shaper": { t: "easing curves for t: Linear, Smoothstep, Ease in/out/in-out, Bounce, Reverse, Triangle, with an integer repeat. End-inclusive: t=1 maps to the end of the curve, so a Frame-driven write-on never snaps back on its final frame; use Triangle for seamless loops.", tags: ["math"] },
  "sheets": { t: "frame-domain sheet selector for layered plexi/glass pieces: Merge-shaped inputs, but exactly ONE passes through — the input whose index equals the current animation frame. Set ANIMATE Frames = wired inputs and every frame is one sheet: the scrubber flips through sheets in the editor, Stack View (S) auto-detects the node and stacks the wired inputs in 3D, and every per-frame export writes one file per sheet. Select Manual pins one sheet regardless of the frame. Each sheet keeps its full pen colors; unwired inputs yield an empty sheet.", tags: ["animation","combine","stack"] },
  "signature": { t: "the artist's mark for a finished plot: signature text, date and edition number in the single-stroke font, anchored to a sheet corner so it lands in the same place on every print. Layout runs the three fields together on one line with the chosen Separator, splits the name off on two lines, or stacks all three; Edition formats the copy number as n/N, No. n or n of N. Font is the hand: Plain is the bare font, Italic leans it, and Hand redraws every stroke with seeded tremor plus per-letter tilt, size and baseline drift, rounding the corners the way a moving nib does — Tremor sets how much, Seed picks a different hand, and the Rule (Underline, Box, Brackets) goes through the same hand so a written mark is not framed by a ruler. Anchor places the block against a corner at Margin distance with Nudge X/Y for the last millimetres, or Custom for a free position. Plot it last on a finer pen.", tags: ["decoration","text"] },
  "simplify": { t: "removes points within a tolerance (Douglas-Peucker-style).", tags: ["pathops"] },
  "singlemarker": { t: "one movable marker at an exact X/Y mm position — at its simplest a solid ink dot (a single spiral stroke). Styles: Dot, Circle, Cross +, Cross ×, Circle + cross (registration style), Circle + dot; a dashed guide shows the spot while the node is selected, and X/Y are value ports so the marker can be animated. Made for marking points: drop several, Merge, then Bridges (Path centers + Source order) joins them in the exact order they are wired into Merge. Every style collapses to exactly one Bridges point at the marker's center. Coordinates: DRO (laser) (2.51) reads X/Y as DRO values — jog the laser dot onto the target, type the reading in, and the marker lands at that exact bed position (laser offset and origin from the machine profile, same convention as Image Underlay anchors).", tags: ["connect","dots","image","spiral","structural","text"] },
  "skew": { t: "X/Y shear in degrees (italicise Text, axonometry from Grid).", tags: ["grid","text","transform"] },
  "skyline": { t: "horizon silhouettes in 1–4 receding layers. Forest: fBm hills with conifer-spike tops and optional trunk texture; City: stepped building skyline with height distribution, antennas and window dashes (some dark). Shares its Horizon Y convention with Water.", tags: ["map","nature","texture","water"] },
  "sliderule": { t: "slide rule scales with the real mathematics: C/D (log), A/B (two decades), K (cubes), CI (inverted C on its own pen — the classic red), L (linear mantissa), S (sines at 1+log10 sin) and T (tangents), each a checkbox. Tick subdivision adapts so gaps never drop below Min tick gap; three graded tick heights, stroke-font numerals and scale letters. Straight stacks a Mannheim rule with body frame and slide separators around B/CI/C; Circular wraps every decade around a full 360° ring — multiplication is angle addition, like a real circular rule. The Cursor position hairline is value-drivable: wire Frame into it and the cursor sweeps the scales.", tags: ["animation","chart","fractal","round","scientific","text"] },
  "smear": { t: "pixel-stretch for lines inside a rectangular zone (guide overlay). Vertical / Horizontal replace zone content with straight axis-aligned streaks at the boundary crossings (sign follows travel direction; Streak length 0 runs to the far edge). Free (bridge) instead joins each path's entry and exit with one straight chord, so the line continues unbroken through the zone. From edge picks which zone edge feeds the effect — e.g. Right continues only right-edge crossings seamlessly along their own tangents while other edges are simply cut. Compare Stretch: that remaps geometry, this replaces it.", tags: ["deform","region","texture"] },
  "smoke": { t: "incense smoke in 3D: a laminar stream rises smoothly, then breaks into turbulent curls past the break height. The line is a ribbon of parallel filaments twisting around the stream and folding like real smoke sheets. Wind bends the column, View yaw orbits it, and Drift wired to Frame makes the smoke flow through an animation. Each filament is one continuous pen stroke.", tags: ["3d","animation","flow","organic","round","warp"] },
  "smoke_mesh": { t: "floating smoke veils in 3D: each sheet is a ribbon surface swept along a noise-wandering spine while the sheet direction rotates (Twist) and folds back on itself (Folds) — drawn as hundreds of parallel filaments, so a face-on veil reads pale and an edge-on fold turns into a dark seam, like long-exposure smoke. Sheets layers 1–4 veils in one camera; Pens spreads a gradient across the sheet; each filament is one continuous stroke. Rotate with View yaw/pitch; wire Frame into Yaw to drift the smoke through an animation.", tags: ["3d","animation","mesh","organic","pens","wave"] },
  "smooth": { t: "smooths paths in two modes. Relax runs an arc-length moving average (Radius mm) over the line — visible on typical densely sampled geometry; endpoints stay pinned and closed paths wrap. Round corners is classic Chaikin corner-cutting for sparse polylines like Random Lines or Delaunay edges.", tags: ["mesh","pathops","round"] },
  "snarl": { t: "a tangle of fishing line: each strand is one continuous stroke with coil memory — curvature relaxes toward the spool loop (Coil mm, Memory sets how firmly), a phase machine alternates loop clusters with long lazy runs, Mess shakes headings and flips handedness into figure-eights, and Loop vary rolls every coiling phase its own loop size from a log-spread so no two loops need match. Clumping pulls strands into attractor centers (seeded Clumps, or wire a path into Clump at to place them — the overlay shows the circles), Clump size sets the dense zone, Tighten shrinks loops inside it and Clump pen splits in-zone segments onto their own pen — the dense-core-in-a-halo look. Strands start from the Edges, the Clumps or Random; soft walls keep the tangle on the sheet.", tags: ["organic","chaos","flow"] },
  "snowflake": { t: "snow crystals with true six-fold symmetry: one arm is grown from the seed and copied round the centre, so every flake is perfectly symmetric while no two flakes in a sheet match. Style Dendrite is a main arm with mirrored side branches at Branch angle and sub-branches to Depth, lengths shrinking toward the tip by Falloff; Fern multiplies the branching into feathers; Stellar keeps few branches and caps every tip with a hexagonal plate over a large sectored core; Plate is a big hexagon with inner rings, spokes and sector windows, its corners sprouting short dendrites; Paper is a child's cut-paper flake — one wedge's jagged profile mirrored round into a closed silhouette, Holes cut-outs mirrored with it, Wobble shaking the scissors. Arms sets the symmetry (6 is snow; 3, 4, 5, 8 and 12 are for art), Tip caps each arm with a plate, needle, fan or arrow, Core sets the centre plate, Width turns centre lines into closed rods tapering to the tips, Rime dots frost along the arms. Layout Rows fills a Count x Rows grid with Jitter; Scatter drops a flurry of different sizes (Size vary) and turns (Spin vary). Fit is shrink-only.", tags: ["nature","symmetry","fractal","repeat"] },
  "solids": { t: "wireframe 3-D: Sphere (lat/lon rings; Solid hides the back hemisphere, Transparent shows all), Cube, Tetra/Octa/Icosa/Dodecahedron (edges derived from geometry). Rotate X/Y/Z, perspective 0–1, position. Rotations are value-drivable — the animation star.", tags: ["3d","animation","mesh","round","space"] },
  "soundline": { t: "turns sound into pen lines. Import a WAV (PCM or float; mixed to mono, peak-normalized, frozen into the patch) and draw it as Wave (the signal as one line) or Envelope (mirrored min/max outline, the classic waveform block). Unwired: stacked Rows inside the margin — a sound poster. Wire paths into Anchor and the sound rides them instead, displacing each line along its normal, the timeline continuing from path to path. Fit maps the clip onto the available length; Speed mm/s plays at a fixed rate and Loop repeats a too-short clip (off: the line goes quiet when the sound ends). Start/Segment slice the clip; Smooth tames noise. Needs the v2.49 fileBinary engine intake.", tags: ["audio","clip","noise","repeat","symmetry","wave"] },
  "spiro": { t: "hypo/epitrochoid gear curves: ring/wheel teeth ratio and pen offset.", tags: ["geometric","round"] },
  "split": { t: "separates paths into multiple outputs by rule (e.g. layer, index).", tags: ["clip","combine"] },
  "splitpens": { t: "(mod / penout) routes every incoming path to the output of its pen - one routing output per pen in PENS order on pins 2 onward, passthrough untouched, unused pens empty, out-of-range layers wrapping modulo the pen count. Pin 1 is a preview tap: the Preview pen selector picks which single pen it carries (or All), and since the preview window shows a selected node's first output, flipping the selector steps through the drawing one color at a time - without ever changing the routing outputs, so nothing can be accidentally soloed out of an export. The natural partner of Portrait's round = pen: split, restyle a round with Set Pen or drop it, and Merge the survivors.", tags: ["penout","pens","plants","portrait","round"] },
  "spore_print": { t: "mushroom spore prints with real gill anatomy: primaries run from the blank stem disc to the rim and shorter lamellula tiers spawn in the widening gaps (closed-form binary hierarchy), keeping line spacing even across the whole cap. Wobble bends the gills at constant mm amplitude, Swirl twists the print, Edge roughens the cap rim, Fade breaks lines into a dusty falloff that strengthens toward the rim, Dust scatters spore specks (own pen), Rim band adds a dense edge ring. Count drops up to six varied caps on one sheet.", tags: ["nature","pens","plants","round","scatter","warp"] },
  "squiggle": { t: "replaces each line with a waveform travelling along it in the path's own frame. Loops draws overlapping pen coils (trochoid — loops appear when Amplitude × 2π exceeds Period); Sine, Triangle and Square are classic waves; Seismic is seeded noise bursts between calm stretches; Glitch holds quantized offset steps that jump every period. On closed paths the period snaps so whole cycles fit and the seam stays continuous. Compare Zigzag's Spine input: that draws wave rows around a path — this rewrites the line itself.", tags: ["audio","deform","noise","spiral","wave"] },
  "stamp": { t: "repeats a motif (or built-in marks; Line + Perpendicular = railway sleepers) along paths, with per-path variation. Takes a Motif input.", tags: ["decoration","repeat"] },
  "starchart": { t: "a coordinate chart drowning in observations, after Roland Kayn's Galaxis. System Polar draws concentric ring bundles (every ring is 1..Band close-set lines with seeded spacing jitter), radial spokes, rim ticks and tangential degree labels, with a clean center Hole for a title; Cartesian rules a banded graph grid with axis numbers instead. Wear breaks the graticule into worn seeded fragments and Wobble gives it a drafting hand. Hits scatters up to thousands of dots through a density field: Patchiness clumps them into drifts and voids, Falloff pulls them outward or toward the center, and every dot is a tiny filled polygon between Dot min and Dot max (small ones common, big ones rare). Grid pen and Hit pen split the layers — graticule in one colour, observations in another.", tags: ["chart","dots","scatter","scientific"] },
  "starfield": { t: "stars (uniform or noise-clustered, size variation) plus connection modes: none, all pairs within a distance, k-nearest, or Constellations (chained 3–9-star figures). Separate star and line pens.", tags: ["connect","noise","pens","space"] },
  "stencil": { t: "pick ONE closed region from the Regions input (index wraps, so the slider steps next/previous — or wire Steps to animate the selection) and clip the Content input inside it, with an edge inset. All-regions mode, outline preview, and browse mode when Content is unwired.", tags: ["animation","clip","combine","region"] },
  "steps": { t: "quantized step sequencer: t is split into N steps patterned as Ramp up/down, Ping-pong or seeded Random, scaled to min/max.", tags: ["math"] },
  "stipple": { t: "organic adaptive stippling (the Kusama look): image darkness sets each dot's SIZE and seeded dart-throwing packs dots until they almost touch, so dark areas become a honeycomb of large concentric-filled cells while light areas thin to sparse specks. Gap is the constant white web between neighbours, Light spread adds extra spacing toward white, Wobble deforms circles into organic blobs (inner rings inherit the shape so fills never cross), Fill pitch matches your pen width for solid blacks.", tags: ["connect","dots","grid","image","round"] },
  "stitchtype": { t: "bitmap lettering dressed in layered stitch marks, in the manner of an 8-bit sampler chart. Text is set in a pixel font (Font Bold 5x7, Sampler 5x7 or Tiny 3x5; A–Z, 0–9, ÄÖÅ, punctuation, | starts a new line) and every font pixel becomes a Pixel × Pixel block of stitch cells. Cells are then classified by distance to the letter boundary, and each class gets its own mark and pen: Core (inside, not touching the outside) carries the fill — Cross X, Plus +, Diamond, Dots, Hatch / or \\, Rings; Edge (the letter's own boundary ring) a lattice of joined plus marks, an Outline, Boxes, Dots or Diagonals; Halo (the ring of cells just outside the letter, 8-connected) horizontal or vertical stripes at Halo stripes / cell, Dashes, Dots or a Zigzag; Aura (the next Aura rings out, 0–3) seeded Dashes, Dots, Ticks or Crosses at Aura fill density, thinning ring by ring. Pins are long seeded bars laid along the halo runs beside the stems (Vertical, Horizontal, Both or None, density Pin density), the pink verticals of the reference chart. Preset Sampler is that reference look (X / lattice / stripes / dashes / vertical pins); Circuit, Knit and Dotted are ready variants; Custom exposes the five mark selectors. Cell mm is the stitch pitch and stays exact unless the block — rings included — cannot fit inside Margin, when it shrinks (never grows). Bridge diagonals fills a 2×2 block where two font pixels touch only at a corner, so Sampler and Tiny diagonals (Z, N, K, X) stay edge-connected instead of falling into corner-touching blocks; Bold is already connected and ignores it. Collinear marks are merged into single strokes — the X fill and the lattice plot as long diagonals and rules, not thousands of ticks — and the Seed only moves pins and aura, so the letter itself is stable while the decoration re-rolls. Five pens by default: Purple core, Blue edge, Red halo, Magenta pins, Orange aura; guides show the margin box, the letter block and the outer ring box.", tags: ["text","grid","weave","fill","retro","decoration"] },
  "stone": { t: "faceted rocks/boulders: irregular polygon outline with interior facet lines from a highlight point (3-D chunk look) and optional hatch shadow (own pen). Layouts: Scatter, Pile (gravity-stacked), Wall (grid — dry-stone look). Angularity from smooth pebble to sharp shard.", tags: ["3d","grid","hatch","nature","physics","scatter"] },
  "stretch": { t: "monotonic band remap: geometry entering the band stretches uniformly along it and everything beyond shifts by the amount — no folds, straight smears. Directional or vanishing-point perspective mode; edge falloff shapes; per-path jitter. The pixel-smear effect, done right. Guide overlay.", tags: ["3d","deform","texture"] },
  "subway": { t: "a transit map in classic Massimo Vignelli style: octilinear routes (0/45/90 only), lines bundling into shared corridors with even spacing and splitting off at 45 degrees, station dots on each line's own pen, larger interchange rings where lines meet, and terminal bars at route ends. Lines cycle through the pens — one color per route.", tags: ["dots","pens","round","structural"] },
  "superformula": { t: "the Gielis superformula: one equation spanning stars, flowers, polygons and diatoms via m/n1/n2/n3. Rings with twist fill the shape concentrically.", tags: ["geometric","plants","round","warp"] },
  "svgimport": { t: "load an SVG file's paths onto the canvas (no text/CSS support).", tags: ["text"] },
  "sweep3d": { t: "a profile repeated along a 3D path and projected flat: the transparent-wireframe sweep where the overlapping outlines build a moiré body (no hidden-line removal, on purpose). Profiles: Circle, Rectangle, Polygon, Star, Line — or wire any paths into the Profile input (fitted to the Width/Height box). Paths: Helix, Cone spiral, Flat spiral, Circle, Figure 8, Line, with elliptical Path width/depth, Rise, Turns, Phase and Path end % for the shrinking spirals. Along the way the profile can taper (End scale %), breathe (Mod amount/cycles, a deterministic sine) and Twist; orthographic Tilt/Yaw view. Fully deterministic — no seed; a point budget coarsens the profile before Instances × resolution explodes.", tags: ["3d","geometric","mesh","round","spiral","warp"] },
  "switch": { t: "a selector gate: the Select value picks which of the wired path inputs passes through; unwired inputs are skipped and the index wraps. Wire Steps into Select for per-frame scene switching.", tags: ["combine"] },
  "symmetry": { t: "mirror/radial kaleidoscope repetition.", tags: ["symmetry","transform"] },
  "tangle": { t: "melts geometry into wandering tangle inside a zone, anchored at the zone edge (guide overlay).", tags: ["deform","region"] },
  "testcard": { t: "calibration sheets: line weight sweep, converging line spacing, hatch density, arcs & tight circles, pen-lift dot grid, fill swatches, registration marks, speed-ramp zigzag, and a Pen palette drawing one labelled swatch per pen (all 12). The three pen tests also come as (thick) variants with series chosen for 2 mm+ nibs — gaps 8→2 mm, hatch 8→2.5 mm, wider pass offsets and 4 mm numerals (they shrink with the cell). Label size mm scales every numeral and the cell titles — a 2.3 mm marker wants ~10 mm to stay legible; the header band grows with it and long titles wrap onto two lines. Or set Pen to the thick pen and keep Label pen fine. Line-spacing groups each stay in their own lane with labels on two alternating rows, hatch labels sit below their squares. The grid auto-shrinks its cells to fit the current canvas.", tags: ["dots","grid","hatch","pens","round","structural"] },
  "textpath": { t: "single-stroke text laid along a wired spine (same font as Text): each glyph sits at its arc-length position rotated to the local tangent. Align Start/Center/End, start offset %, baseline offset along the normal, Flip side, Repeat-to-fill with gap, curve sampling. Open and closed spines; falls back to a horizontal line when unwired.", tags: ["text"] },
  "tiles": { t: "grid of tiles, each a separate closed path: parametric Superellipse, Circle, Triangle, Hexagon, Star, Reuleaux, Cross, with per-tile rotation and jitter. Layout: Grid, Brick (offset rows) or Hex pack (0.866 pitch — circles and hexagons at Size 100 touch their neighbours); Alternate flip rotates every other tile 180° so triangles tessellate. The natural Explosion input.", tags: ["geometric","grid","round","tiling"] },
  "tileshuffle": { t: "(deform) — the canvas is cut into a grid and tiles are permuted with optional flips/180s (bounds-safe). Cuts at tile borders are exact, so no ink is lost at the seams. Amount selects how many tiles join the shuffle.", tags: ["clip","deform","grid","tiling"] },
  "topolar": { t: "(deform) — cartesian-to-polar remap: x becomes angle, y becomes radius, bending any horizontal composition into rings, discs or fans. Turns, start angle and inner radius shape the wrap.", tags: ["deform","round"] },
  "torn": { t: "rips the wired paths open along a tear band: every crossing deterministically bridges the gap as one straight span, is flung aside as a coherent burst (Fling mm reach, Chaos angular spread), or snaps into two spiky loose ends — Fling % / Snap % set the mix, the rest bridge. Gape pushes intact geometry apart so the wound opens, Ragged roughens the edge, Detail resamples the input first. Tearing is vertex-based: sparse inputs (e.g. 2-point stripes from Op Tunnel) tear whole-segment with hard quantized edges — raise Detail for smooth edge cuts; both are intended looks. Stack several Torn nodes for multiple rips; classic pairings: Loom → Torn, Op Tunnel → Torn.", tags: ["chaos","clip","connect","weave"] },
  "traceimg": { t: "legacy alias, hidden from the palette since 2.51: merged into Image as the Contours (trace) render mode. Old patches keep loading and rendering unchanged (byte-identical compute).", tags: ["image","terrain"] },
  "travelsort": { t: "(penout) — greedy nearest-neighbour reordering of the plot: open paths may be reversed, closed loops are entered at the vertex nearest the pen, and pen groups stay intact. Same geometry, drastically less pen-up travel; place last before export.", tags: ["penout"] },
  "travelstop": { t: "inserts a pause or pen-change after a set distance of drawing, for wearing/refilling media (chalk, charcoal, dip/fountain pens). Every N mm of drawn length it tags the next path so the G-code lifts and pauses (M0) with your message (\"Advance chalk / refill\"), or treats it as a pen change. Unlike the machine profile's Maintenance pause (which is fixed per machine), this lives in the graph and travels with the patch. Place it LAST and keep route optimize off so the distance spacing stays accurate.", tags: ["penout","pens"] },
  "trimext": { t: "shortens or lengthens path ends.", tags: ["pathops"] },
  "truchet": { t: "tiled quarter-circle patterns. Tiles mode draws arc or diagonal tiles; Tile fill leaves a seeded share of tiles empty; Separate clamps arc radii and forces an edge gap so strands never meet or cross. Loop mode grows a spanning tree and emits one single closed line that fills the canvas — a maze you can plot without lifting the pen.", tags: ["geometric","maze","plants","round","tiling"] },
  "truchet_multi": { t: "the Carlson-style multiscale sibling of Truchet: strands cross cell edges at fixed stations, and the node chains them tile to tile, so the labyrinth comes out as closed loops and border-to-border strokes instead of thousands of tiny arcs. Strands 1–4 parallel lines, Tiles Arcs / Lines (45° chamfers) / Mixed, Subdivide + Sub levels split seeded cells into quarter-size tiles (strands break at scale seams — that is the style), Pens by depth inks each scale level separately.", tags: ["geometric","grid","maze","pens","tiling","weave"] },
  "trunks": { t: "birch trunks only, no branches: two wandering edge lines per trunk. Smoothness (edge waver), lean, upward taper, and Artifacts: horizontal bark dashes (some doubled), on their own pen if desired.", tags: ["nature","plants","wave"] },
  "tubes": { t: "tubes wandering and crossing in 3D, projected with perspective and drawn with real hidden lines: tubes break where they pass behind each other and their own back side is hidden. Surface is one continuous spiral per tube or a ring-and-line wireframe; radius is noise-modulated; wire Drift to animate.", tags: ["3d","animation","mesh","noise","spiral","structural"] },
  "turtle": { t: "classic turtle graphics from a command string: F/B move drawing, M moves pen-up, R/L turn, U/D pen up/down, [ ] branch, N[...] repeats. Preset picks a ready-made program (Hex flower, Pentagram, Spun squares, Rose window, Radial burst, Turning square, Branch tree, Zigzag ribbon); Custom uses the Program field. Auto-fits to the sheet; deterministic.", tags: ["geometric","plants","repeat"] },
  "tvnoise": { t: "analog-TV static: cells randomly filled with square/circle pixels or horizontal scanline dashes; size/position jitter and rolling interference bands that modulate density row-wise. Budget-capped.", tags: ["noise","round","scientific"] },
  "typegrating": { t: "typography concealed inside a strict line grating, readable up close, op-art from a distance. The single-stroke font is thickened into a mask and shaped by a Glyph style first: Plain, Modular (letterforms quantized onto a module grid — blocky Atype abstraction), Fragments (a seeded window of each stroke), Outline (only the edge band disturbs the grating) or Stencil (periodic cuts cleared ACROSS the thick stroke). The grating reacts with Break / Phase shift (half-pitch square jogs, one continuous stroke per column) / Density / Dashes / Weight; Invert swaps figure and ground, Slant shears an italic, text auto-fits the margin box.", tags: ["chart","clip","grid","retro","text"] },
  "typerain": { t: "typewriter art as rain: the sheet becomes a fixed character grid (Size sets the cap height, Pitch X / Pitch Y the cell in cap-height units — a real machine sits near 1.2 × 1.7) and every column (Direction Down) or row (Right) is filled with seeded runs, each run one glyph from Glyphs repeated cell after cell on one pen, separated by at least Gap empty cells. Repeat a character in Glyphs to weight it; lowercase is typed as capitals, unknown characters are dropped, an empty field types M. Bars turns a share of the runs into solid ruled lines through the cell centres, Slashes forces a share into / ladders — the diagonal stairs of the original. Density is the filled share of every lane (0 types nothing), Run length and Run variation shape the runs (most short, a few long). Grid Strict keeps every run on the row pitch; Free lets each run slip a fraction of a cell like a platen that was never quite aligned. Double strike overtypes each glyph with a 0.15 mm shift, once or twice, for the heavy-ribbon look (the ink box is centred in the cell, so the shifts never leave it). Pens used from First pen picks a seeded colour per run. Wire closed shapes into Mask and the rain falls only inside them (bars break at the mask edge). Cells are typed lane by lane, so a point-budget cut loses the far lanes first.", tags: ["grid","retro","scatter","text"] },
  "tyylita": { t: "applies a Stroke style to existing paths.", tags: ["style"] },
  "videotest": { t: "a collection of broadcast and imaging test cards redrawn as pen-plotter line art: Philips circle (the PM5544 composite — 19×14 crosshatch, geometry circle, castellations, colour bar band, multiburst gratings, staircase and the two station-text boxes), EIA 1956 resolution (converging TVL wedges at the centre and in all four corners, focus circles, greyscale steps, stripe boxes, overscan border arrows), Monoscope grid, Convergence crosshatch, Convergence dots, Siemens star, Zone plate (true Fresnel spacing — ring radii follow the square root of the index, so every ring encloses the same area), Multiburst sweep, Colour bars (the EBU seven over reversed castellations, a PLUGE wedge and the white/black references), Greyscale staircase, Overscan frames, Focus chart, Checkerboard, Line-pair ladder and Circle geometry. A pen cannot lay down grey, so every tone is hatched: Tone and Ink spacing set the density and the greyscale steps ramp their hatch spacing instead of their darkness — the honest translation of a grey ramp. Aspect letterboxes the card into a true 4:3, 16:9 or 1:1 frame, because a test card drawn at the wrong ratio tests nothing. Colour elements map onto the palette (bars run Gray / Ochre / Sky / Green / Magenta / Red / Blue, the closest analogues of the EBU order) or collapse onto one pen. Two knobs turn the instrument back into an image: CRT warp barrels or pincushions the card (pinned at the corners, so it never leaves the sheet) and Line jitter tears each scan line sideways with seeded noise.", tags: ["chart","geometric","grid","halftone","retro","scientific"] },
  "view3d": { t: "(deform) — puts the drawing into 3D and views it from any angle: yaw/pitch/roll with adjustable perspective (0 = isometric, 1 = dramatic). Z source Flat tilts the sheet like paper, Pens stacked gives each pen layer its own depth (parallax when rotated), Noise relief bends the drawing over a heightfield. Wire Frame into Yaw for a spinning-drawing animation.", tags: ["3d","animation","deform","noise","pens"] },
  "viiva": { t: "not geometry: produces a style (dash patterns etc.) for generators' Style inputs.", tags: ["style"] },
  "vision_chart": { t: "a plotter-native eye-chart studio: geometrically scaled Landolt C and equal-arm Tumbling E logMAR charts, Chinese 5-mark and Golovin-Sivtsev layouts, and a seeded two-pen pseudoisochromatic plate whose hidden number is packed with its own finer dots so it reads as a figure rather than a smudge. Distance, Top logMAR and Scale set true optotype size — every row is scaled by the logMAR step and the outermost stroke lands exactly on the nominal diameter, so the chart is dimensionally honest; the 2.5 m default suits an A4 sheet and 5 m fills it with the largest rows only. Ink pitch should match the pen. Artistic and educational output — not a certified medical test.", tags: ["chart","dots","scientific","text"] },
  "volcano": { t: "a 3-D volcano with hidden-line removal: the flank climbs to a crater rim, then dips into a bowl. Render as Rows (terrain scanlines), Rings, Spokes, Mesh or Dots (polar grid of small circles sized by altitude, with grow direction and seeded size jitter). Tilt is the viewing elevation — low angles hide the crater floor behind the near rim; Yaw spins the volcano (flutes, rock noise, spokes and dots turn with it). Steepness, Dip, fBm Roughness and radial Flutes shape the rock. Animate Tilt or Yaw with the frame clock for a fly-over.", tags: ["3d","chart","dots","geometric","mesh","terrain"] },
  "voronoi": { t: "seeded sites carved into cells by half-plane clipping, with optional Lloyd relaxation (0-3) for even cell sizes. Shared edges are emitted exactly once, so no line is drawn twice. Optional site crosses.", tags: ["clip","geometric","mesh"] },
  "warp": { t: "4-corner perspective or full lattice grid deformation.", tags: ["3d","deform","grid","warp"] },
  "water": { t: "lake/sea surface: ripple rows compressed toward a horizon (perspective), wave + slower swell + noise, and Choppiness that breaks lines into glinting dashes via a noise gate.", tags: ["3d","nature","noise","water","wave"] },
  "wave_hatch": { t: "wave bands of dense vertical strokes: blank noise-wave seams (structurally non-crossing) divide the sheet and every band fills with tight upright lines seam to seam. Seam gap is the negative space that draws the waves; Lean fans the strokes with the local slope, Hand wobble bends them and jitters the pitch for the hand-hatched textile read. Serpentine ordering for plotting economy.", tags: ["geometric","hatch","noise","wave"] },
  "whale": { t: "line-drawn whales in two hands, with an octopus hiding in the Species list. Simple is a child's whale: a fat blob body, heart-shaped flukes, a fountain Spout, one eye, a smile, a belly line and a flipper, every stroke shaken by Wobble %; the Simple octopus is a round head with two eyes, a smile and 6–8 wiggly arm strokes. Detailed is a naturalist's ink drawing: a species body profile (Blue, Humpback, Sperm, Orca, Narwhal or Generic) with the flukes turned to show both lobes — the near one lower and larger, the far one foreshortened above, a notch between — a species dorsal (tall triangle, hump, small hook, sperm-whale knuckles, narwhal ridge), a swept flipper (humpback's a third of the body with a scalloped edge), eye, mouth line (the sperm whale's runs along the underside of its box head), spout, and Skin texture markings: throat pleats on the baleen whales, humpback tubercles, sperm-whale wrinkles, blue-whale mottle, orca eye patch, saddle and belly boundary, the narwhal's tusk with its spiral hatching and back spots. Octopus swaps the whole plan: a mantle egg and head circle walked as one silhouette, slit-pupil eyes, a siphon, eight tapered arms fanning from under the head as closed limbs with suckers along the inner edge, and papillae on the mantle. Mixed rolls style and species per creature. Layout, Facing, Heading, Spine mount, shrink-only fit and the point-budget order work exactly as in Fish. Bodies carries the closed silhouettes: one per whale, mantle plus each of the eight arms for an octopus.", tags: ["creature","nature","water","organic"] },
  "windtunnel": { t: "streamlines flowing around the closed shapes wired into Obstacle, like smoke lines in a wind tunnel: a uniform flow (Angle) is steered tangentially inside the Influence band, so lines hug and part around the object at Clearance distance — never inside it (a hard projection guarantees the gap). Hug shapes how abruptly they wrap; Waviness meanders the whole field; Wake turbulence churns the flow behind each shape and dies out over Wake length. Keep shape passes the obstacle through on its own pens; unwired Obstacle gives plain flow lines. All closed input shapes act as obstacles — wire one via Stencil to aim the tunnel at a single potato.", tags: ["combine","flow","pens","region"] },
  "wood": { t: "tree cross-section: growth rings with year-width variation grouped by slow noise, shared angular wobble (rings never cross), eccentric reaction-wood stretch, radial drying cracks, rough bark, pith. Grain mode instead renders the split-face cathedral flame arches with vertical checks.", tags: ["nature","noise","plants","round","texture"] },
  "worm": { t: "worm or centipede: an inertia-walk spine dressed in flattened cross-hoops with a tapered width profile (round head, pointed tail). Centipede adds two-joint leg pairs with alternating gait; optional antennae.", tags: ["creature","nature","round"] },
  "woven_ribbon": { t: "a multi-track ribbon woven over and under itself: a seeded lattice walk (no edge reused; an already-visited point is crossed straight through, so crossings are always perpendicular) becomes a spine with exact corner arcs, offset into a center line plus Offset pairs parallel tracks. At every self-crossing the under pass is clipped by the full over-pass width plus Gap — cover-underpasses weaving, so nothing in the output intersects (validated). Weave: Alternate (basket parity), Later over, Earlier over; End caps close the loose ends with nested semicircles. Fill Tracks draws the parallel tracks; Rays replaces them with a perpendicular comb across the whole ribbon width every Ray step along the spine — the teeth fan out on the outside of every bend like radial-comb lettering — and Square wave draws that same comb as ONE continuous meander (across, along the edge, back across), the plotter-friendly version; both keep the under-pass gaps, and Ray overhang lets the teeth stick out beyond the ribbon. Two-tone comb cuts every tooth at the Split line (0 = the spine, ±1 = an edge) and draws the two halves on Pen and Second pen — for Square wave that is two meanders sharing the split line, each zigzagging on its own.", tags: ["clip","grid","structural","weave"] },
  "zen_garden": { t: "karesansui raked gravel around the closed shapes wired into Stones (one Photo Trace outline, several via Merge, or any closed shapes). Each stone sits in a pool of offset rings (Rings, starting at Clearance, traced from an exact euclidean distance field), and the background rake grooves end cleanly where they meet the outermost ring. Rake: Straight (Direction), Waves (sine meander), Circular (rings from the canvas centre), Rings only (rings expanding until they fill the sheet). Spacing is the groove pitch; Tines splits every groove into a comb of parallel lines with Tine gap between them, like the teeth of a real rake. Wobble adds seeded hand-raked imperfection, Detail is the field grid cell in mm. Lines never enter a stone or its clearance. Keep stones passes the outlines through on Stone pen.", tags: ["combine","nature","region","texture"] },
  "zigzag": { t: "rows of zigzag, sine or square waves. Skew tilts the zigzag toward a sawtooth; Envelope modulates amplitude with a seeded noise envelope (bursts and quiet passages); Row phase offsets rows for interference. Wire any path into Spine and the waves follow it as parallel offset rows.", tags: ["audio","geometric","noise","wave"] },
  "zigzag_path": { t: "redraws every input path as a patterned stroke following the original line. Mode: Zigzag (sharp triangle wave, apex points inserted analytically so corners stay exact), Sine (smooth wave) or Coil (dense serpentine — perpendicular runs joined by rounded U-turns, pitch = half the Wavelength). Amplitude is the half-width; Vary amp and Vary wavelength drift the pattern smoothly over the Vary length scale via seeded noise — hand movement, not per-vertex jitter. Fade mm ramps open strokes smoothly in and out at both ends (in Coil the runs shrink toward the tips); closed paths snap to whole periods and the drift wraps seamlessly. Each path keeps its own pen.", tags: ["deform","texture","wave"] },
  "zine": { t: "imposition for folded booklets: wired compositions are laid onto the sheet in the order the FOLDS require, so the plotted sheet folds into a finished zine. Each input is a full-canvas composition scaled into its page panel, as in Mini Canvas, and the page pins appear and disappear with the Format — 8-page mini zine (the classic one-sheet, one-cut zine: the top row prints upside down and the middle slit is drawn for you), 4-page folio, 8- and 16-page saddle stitch (2-up per sheet side, Sheet picks the sheet of the stack) and Accordion (3–12 panels, optionally continuing on the back). Double-sided work runs through Side: plot Front, turn the paper over, switch to Back and plot again. The back imposition is derived, never typed — the reverse of page k is its own recto/verso partner and its panel mirrors according to Flip axis (Long edge keeps the artwork upright, Short edge turns it 180°) — so pages land back-to-back with no hand arithmetic. Registration marks print at identical sheet coordinates on both sides and are symmetric under both flips, so they overprint themselves when the sheet is turned. Because a page panel rarely has the sheet's proportions, Scaling decides who gives way: Fit letterboxes, Fill crops (the overlay then draws the surviving source region on the canvas), Stretch distorts, and Rotate 90 + Fit lands exactly on A-series page proportions — an A4 landscape canvas rotated is an A4 portrait page, full bleed and no distortion, the artwork simply reading sideways on the sheet. Trim marks, fold ticks or dashed fold lines, the cut slit and panel frames go on the Mark pen; Page numbers draws a numeral in each panel in that panel's own orientation — print once, fold it, and the imposition is proven.", tags: ["clip","combine","grid","repeat","structural"] },
};
